(function(){
  'use strict';
  const cfg=window.SUCANEITOR_CLOUD_CONFIG;
  const db=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseKey);
  const E=window.ReservaEngine;
  const $=id=>document.getElementById(id);
  const state={access:null,linkToken:null,publicCreate:false,context:null,actor:null,locals:[],reasons:[],configs:{},receptionSchedules:[],newItems:[],current:null,editingId:null,orderCandidates:[],orderCandidatesLocal:null,qrTokens:new Map(),view:'active',timer:null,channel:null,realtimeTimer:null,realtimeMode:'idle',listRequests:{active:0,history:0},listSignatures:{active:null,history:null},detailRequest:0,detailSignature:null,productCatalog:null,productCatalogPromise:null,productSearchIndex:[],productSearchType:'nombre',productSearchRequest:0};
  const sourceLabels={local:'Disponible en el local',proveedor:'Esperando proveedor',pedido_local:'Pedido a otro local'};
  const managementLabels={crear:'Crear pedido entre locales',existente:'Vincular un pedido existente',externo:'Coordinado fuera del sistema'};
  const purposeLabels=E.purposes||{retiro_cliente:'Retiro del cliente en el local',reparto:'Reparto del local',pedido_web:'Pedido web',traslado_interno:'Traslado interno entre locales',otro:'Otro destino'};
  const deliveryLabels=E.deliveries||{retiro_local:'Retiro en el local',reparto_local:'Reparto del local',agencia:'Agencia o correo'};
  const transportLabels=E.transports||{reposicion:'Próxima reposición',agencia:'Agencia o transporte tercero',propio:'Traslado propio',coordinar:'A definir'};
  const uuid=/^[0-9a-f]{8}-[0-9a-f-]{27}$/i;
  function html(v){return String(v==null?'':v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
  function reservationNumber(r){return String(r?.numero??r?.number??r?.codigo??r?.code??'');}
  function js(v){return String(v||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/[\r\n]/g,' ');}
  function fmt(v){if(!v)return '—';try{return new Date(v).toLocaleString('es-UY',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch(_){return String(v);}}
  function clean(v,max=1000){return E.cleanText(v,max);}
  function labelText(v,max=260){const value=clean(v).replace(/\s+/g,' ').trim();return value.length>max?value.slice(0,max-1)+'…':value;}
  function tokenFromHash(){const raw=decodeURIComponent(location.hash.slice(1)).trim();return /^[a-f0-9]{48,128}$/i.test(raw)?raw:null;}
  function toast(message,type='ok'){const el=$('toast');el.textContent=message;el.className='toast show'+(type==='error'?' error':'');clearTimeout(state.timer);state.timer=setTimeout(()=>el.className='toast',3300);}
  function fail(error,where){console.error(where||'[Reservas]',error);toast(error?.message||String(error)||'No se pudo completar la acción','error');}
  async function rpc(name,args={}){const {data,error}=await db.rpc(name,args);if(error)throw error;return data;}
  function withAccess(args={}){return {...args,p_acceso:state.access||null};}
  function trackingUrl(token){return `${location.origin}/reserva#${encodeURIComponent(token)}`;}
  function setBusy(button,busy,label){if(!button)return;button.disabled=busy;if(busy){button.dataset.label=button.textContent;button.textContent=label||'Guardando…';}else if(button.dataset.label){button.textContent=button.dataset.label;delete button.dataset.label;}}
  function localByName(name){return state.locals.find(x=>x.nombre===name);}
  function isAdmin(){return state.actor?.supervisor===true;}
  function selectedLocal(){return isAdmin()?($(`${state.view==='history'?'history':'active'}-local`)?.value||state.actor.local):state.actor?.local;}

  async function init(){
    state.linkToken=tokenFromHash();
    if(state.linkToken){state.publicCreate=true;state.access=state.linkToken;return openApp();}
    const {data:{session}}=await db.auth.getSession();
    if(!session){
      $('boot').hidden=true;$('access-missing').hidden=false;return;
    }
    await openApp();
  }

  async function openApp(){
    state.context=await rpc('op_reserva_contexto',withAccess());state.actor=state.context.actor;state.locals=state.context.locals||[];state.reasons=state.context.reasons||[];state.configs=state.context.config||{};state.receptionSchedules=state.context.reception_schedules||[];
    $('boot').hidden=true;$('access-missing').hidden=true;$('app').hidden=false;
    document.body.classList.toggle('public-create',state.publicCreate);
    $('actor-name').textContent=state.publicCreate?'Solo creación':state.actor.name;$('current-local').textContent=state.publicCreate?state.actor.local:isAdmin()?'Todos los locales':state.actor.local;
    document.querySelectorAll('.admin-only').forEach(x=>x.hidden=!isAdmin());
    fillLocalSelectors();resetForm();
    if(state.publicCreate){
      $('refresh-button').hidden=true;$('manage-link').textContent='Gestionar reservas';$('manage-link').href='/?module=reservas';
      document.querySelector('[data-cancel-form]').textContent='Limpiar formulario';showView('new');return;
    }
    bindRealtime();showView('active');
    const params=new URL(location.href).searchParams,qr=params.get('qr'),open=params.get('open');if(qr)await resolveQr(qr);else if(open&&uuid.test(open))await openDetail(open);
  }

  function fillLocalSelectors(){
    const options=state.locals.map(l=>`<option value="${html(l.nombre)}">${html(l.nombre)} (${html(l.almacen)})</option>`).join('');
    ['new-local','active-local','history-local','settings-local'].forEach(id=>{const el=$(id);if(!el)return;el.innerHTML=options;el.value=state.actor.local||state.locals[0]?.nombre||'';});
    document.querySelectorAll('.supervisor-local').forEach(x=>x.hidden=!isAdmin());
    $('new-local').disabled=!isAdmin();
    fillScheduleOriginOptions();
  }
  function fillScheduleOriginOptions(){const select=$('schedule-origin-local');if(!select)return;const destination=$('settings-local')?.value||state.actor?.local,previous=select.value;const rows=state.locals.filter(l=>l.nombre!==destination);select.innerHTML='<option value="">Elegí un local…</option>'+rows.map(l=>`<option value="${html(l.nombre)}">${html(l.nombre)} (${html(l.almacen)})</option>`).join('');if(rows.some(l=>l.nombre===previous))select.value=previous;}
  function sourceDays(item){const local=$('new-local').value||state.actor.local,type=item.procedencia==='pedido_local'?'local':'proveedor',origin=String(type==='local'?item.origen_local:item.proveedor_nombre||'').trim().toLocaleLowerCase('es');return state.receptionSchedules.find(x=>x.local_nombre===local&&x.origen_tipo===type&&String(x.origen_nombre).trim().toLocaleLowerCase('es')===origin&&x.activo)?.dias_recepcion||[];}
  function receptionHint(item){
    if(item.procedencia==='local'){
      if(item.separacion_estado==='completa')return 'Ya está separado para esta reserva: el próximo paso será avisar, despachar o entregar. No necesita fecha estimada ni remito.';
      if(item.separacion_estado==='parcial')return `Hay ${item.cantidad_local||0} de ${item.cantidad} unidades separadas. El seguimiento continuará hasta apartar las restantes.`;
      if(item.separacion_estado==='pendiente')return 'Está disponible en este local, pero todavía falta retirarlo de góndola o depósito general y colocar la etiqueta.';
      return 'Elegí si el producto ya quedó físicamente separado. “Disponible en el local” solo indica su origen.';
    }
    const days=sourceDays(item),labels=['domingo','lunes','martes','miércoles','jueves','viernes','sábado'],origin=item.procedencia==='pedido_local'?item.origen_local:item.proveedor_nombre;
    if(!origin)return 'Seleccioná el proveedor o local de origen.';
    if(item.procedencia==='pedido_local'){
      const route=transportLabels[item.traslado_tipo]||transportLabels.coordinar;
      const schedule=days.length?` Días habituales desde ${origin}: ${days.map(d=>labels[d]).join(', ')}.`:'';
      return `${route}: el local de origen prepara la mercadería; luego se registra el despacho y recién al recibirla se carga como separada en este local.${schedule}`;
    }
    return days.length?`Días habituales de recepción desde ${origin}: ${days.map(d=>labels[d]).join(', ')}. La fecha estimada es opcional y puede modificarse.`:`Esperando a ${origin}. Indicá una fecha solamente si fue confirmada.`;
  }
  function showView(view){
    if(state.publicCreate&&view!=='new')view='new';
    if(view==='settings'&&!isAdmin())view='active';state.view=view;
    document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`view-${view}`));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===view));
    if(view==='active'||view==='history')loadList(view);if(view==='settings')renderSettings();if(view==='new')setTimeout(()=>$('product-search')?.focus(),50);
  }

  async function loadList(kind=state.view,{silent=false}={}){
    const history=kind==='history',listEl=$(history?'history-list':'active-list'),request=++state.listRequests[kind],hadContent=listEl.dataset.loaded==='true';
    if(!hadContent&&!silent)listEl.innerHTML='<div class="empty">Actualizando reservas…</div>';
    listEl.classList.add('is-syncing');listEl.setAttribute('aria-busy','true');
    try{
      const rows=await rpc('op_reserva_listar',withAccess({p_filtros:{history,search:clean($(history?'history-search':'active-search').value),estado:$(history?'history-state':'active-state').value,local:isAdmin()?$(history?'history-local':'active-local').value:null}}));
      if(request!==state.listRequests[kind])return;
      const safeRows=rows||[],signature=JSON.stringify(safeRows);
      if(signature!==state.listSignatures[kind]){renderCards(safeRows,listEl);state.listSignatures[kind]=signature;}
      listEl.dataset.loaded='true';if(!history){$('active-count').textContent=safeRows.length;renderStats(safeRows);}
    }catch(error){if(request!==state.listRequests[kind])return;if(!hadContent)listEl.innerHTML=`<div class="empty">${html(error.message)}</div>`;else console.warn('[Reservas] No se pudo actualizar la lista en segundo plano.',error);}
    finally{if(request===state.listRequests[kind]){listEl.classList.remove('is-syncing');listEl.removeAttribute('aria-busy');}}
  }
  function renderStats(rows){const count=s=>rows.filter(x=>x.estado===s).length;const ready=count('listo'),unwarned=rows.filter(x=>x.estado==='listo').length,late=count('vencido');$('stats').innerHTML=`<div class="stat"><span>Total activas</span><strong>${rows.length}</strong></div><div class="stat"><span>Con mercadería</span><strong>${rows.filter(x=>Number(x.unidades_local)>0).length}</strong></div><div class="stat attention"><span>Listas para avisar</span><strong>${unwarned}</strong></div><div class="stat overdue"><span>Más de 48 h</span><strong>${late}</strong></div>`;}
  function renderCards(rows,target){
    if(!rows.length){target.innerHTML='<div class="empty">No hay reservas para mostrar.</div>';return;}
    target.innerHTML=rows.map(r=>{const p=E.progress(r),d=E.deadlineInfo(r.vencimiento_at),purpose=purposeLabels[r.finalidad]||r.motivo_nombre||'Reserva';return `<button class="reservation-card ${r.estado==='vencido'?'overdue':''}" type="button" data-reservation-id="${r.id}"><div class="card-top"><span class="code">#${html(reservationNumber(r))}</span><span class="badge ${r.estado}">${html(E.labels[r.estado]||r.estado)}</span></div><h3>${html(E.customer(r))}</h3><p>${html(purpose)} · Responsable: ${html(r.responsable_nombre)}</p><div class="progress-row"><span>${r.unidades_local||0} en local · ${r.unidades_entregadas||0} entregadas</span><b>${p}%</b></div><div class="progress"><i style="width:${p}%"></i></div><div class="card-bottom"><span>${html(r.local_nombre)} · ${fmt(r.created_at)}</span><span class="deadline ${d.kind==='late'?'late':''}">${html(d.label)}</span></div></button>`;}).join('');
  }

  async function openDetail(id,{silent=false}={}){
    const request=++state.detailRequest,sameReservation=state.current?.reservation?.id===id&&!$('detail-modal').hidden;
    if(!sameReservation&&!silent)$('detail-content').innerHTML='<div class="empty">Cargando detalle…</div>';
    $('detail-modal').hidden=false;$('detail-content').classList.add('is-syncing');$('detail-content').setAttribute('aria-busy','true');
    try{
      const detail=await rpc('op_reserva_detalle',withAccess({p_reserva:id}));if(request!==state.detailRequest)return;
      const signature=JSON.stringify(detail);state.current=detail;
      if(!sameReservation||signature!==state.detailSignature){renderDetail();state.detailSignature=signature;}
    }catch(error){if(request!==state.detailRequest)return;if(silent&&sameReservation)console.warn('[Reservas] No se pudo actualizar el detalle en segundo plano.',error);else{closeDetail();fail(error);}}
    finally{if(request===state.detailRequest){$('detail-content').classList.remove('is-syncing');$('detail-content').removeAttribute('aria-busy');}}
  }
  function itemOriginLabel(item){const base=sourceLabels[item.procedencia]||E.sources[item.procedencia]||item.procedencia;if(item.procedencia==='proveedor')return `${base}${item.proveedor_nombre?` · ${item.proveedor_nombre}`:''}`;if(item.procedencia==='pedido_local')return `${base}${item.origen_local?` · Desde ${item.origen_local}`:''}${item.pedido_local_gestion?` · ${managementLabels[item.pedido_local_gestion]||item.pedido_local_gestion}`:''} · ${transportLabels[item.traslado_tipo_actual||item.traslado_tipo]||transportLabels.coordinar}`;return base;}
  function preparedAtOrigin(item){return Number(item.cantidad_preparada_origen??item.cantidad_origen??0);}
  function itemStatusLabel(item,reservationState){if(Number(item.cantidad_entregada)>=Number(item.cantidad))return 'Entregado';if(reservationState==='cancelado')return 'No entregado';if(Number(item.cantidad_local)>0)return Number(item.cantidad_local)+Number(item.cantidad_entregada)>=Number(item.cantidad)?'Separado completo':'Separado parcial';if(item.estado==='en_transito')return 'En tránsito';if(item.estado==='preparado_origen'||preparedAtOrigin(item)>0)return 'Separado en origen';if(item.procedencia==='local')return 'Pendiente de separar';if(item.procedencia==='proveedor')return 'Pendiente de proveedor';return item.pedido_estado==='pendiente'?'Esperando respuesta del local':'Pendiente de envío';}
  function itemProcessMarkup(item){
    if(item.procedencia==='local')return '<div class="process-strip"><strong>Proceso en este local</strong><span>Separar → etiquetar → avisar o despachar → entregar.</span></div>';
    if(item.procedencia==='proveedor')return `<div class="process-strip"><strong>Recepción de proveedor</strong><span>Esperar proveedor → controlar remito → separar → etiquetar → entregar.</span></div>`;
    const prepared=preparedAtOrigin(item),actualTransport=item.traslado_actual||item.traslado_detalle||'',tracking=item.tracking_actual||item.tracking||'',linked=item.pedido_id;
    return `<div class="process-strip"><strong>Traslado ${html(item.origen_local||'otro local')} → ${html(state.current?.reservation?.local_nombre||'este local')}</strong><span>${linked?'El pedido entre locales controla aceptación, preparación, reposición y despacho.':'La coordinación externa se actualiza desde esta reserva.'}</span><div class="origin-progress"><span><b>${prepared}</b> separadas en origen</span><span><b>${item.cantidad_local||0}</b> recibidas aquí</span>${item.pedido_estado?`<span>Pedido: <b>${html(item.pedido_estado)}</b></span>`:''}${item.pedido_reposicion_id?'<span><b>Asignado a reposición</b></span>':''}${actualTransport?`<span>Transporte: <b>${html(actualTransport)}</b></span>`:''}${tracking?`<span>Seguimiento: <b>${html(tracking)}</b></span>`:''}</div></div>`;
  }
  function nextStep(r,items){
    if(E.isTerminal(r.estado))return null;
    if(r.estado==='vencido')return {action:'exception',eyebrow:'RESERVA VENCIDA',title:'Resolver el plazo vencido',description:'Si la mercadería seguirá separada, registrá una excepción con nuevo plazo y motivo. Para entregar o cancelar usá las acciones adicionales.',label:'Registrar excepción'};
    if(r.estado==='avisado'||r.estado==='parcial')return {action:'finish',eyebrow:'SIGUIENTE PASO',title:r.estado==='parcial'?'Completar la entrega pendiente':'Entregar al cliente o cerrar el proceso',description:'Indicá qué ocurrió y cuántas unidades salieron. Si queda mercadería, la reserva continuará abierta.',label:r.estado==='parcial'?'Completar entrega':'Registrar entrega o cierre'};
    if(r.estado==='listo'){
      if(r.finalidad==='reparto')return {action:'finish',eyebrow:'SIGUIENTE PASO',title:'Entregar la reserva al reparto',description:'Verificá la dirección, entregá todos los bultos al reparto y registrá la salida.',label:'Registrar salida en reparto'};
      if(r.finalidad==='pedido_web'&&r.entrega_tipo!=='retiro_local')return {action:'finish',eyebrow:'SIGUIENTE PASO',title:'Despachar el pedido web',description:'Controlá el número del pedido, la dirección y todos los productos antes de registrar el despacho.',label:'Registrar despacho web'};
      if(r.finalidad==='traslado_interno')return {action:'finish',eyebrow:'SIGUIENTE PASO',title:'Completar el traslado interno',description:'Confirmá que todos los bultos salieron hacia el local indicado y registrá el cierre.',label:'Registrar envío al local'};
      return {action:'state:avisado',eyebrow:'SIGUIENTE PASO',title:'Avisar al cliente',description:'Contactá al cliente y, cuando el aviso esté hecho, dejalo registrado para que el equipo sepa que puede entregar.',label:'Confirmar que el cliente fue avisado'};
    }
    const pending=items.filter(item=>Number(item.cantidad_local||0)+Number(item.cantidad_entregada||0)<Number(item.cantidad||0)),hasLocal=pending.some(item=>item.procedencia==='local'),hasExternal=pending.some(item=>item.procedencia!=='local');
    if(hasLocal&&!hasExternal)return {action:'receive',eyebrow:'SIGUIENTE PASO',title:'Separar la mercadería disponible en el local',description:'Retirá las unidades de góndola o depósito general, reunilas para esta reserva y colocá la etiqueta.',label:'Registrar separación'};
    if(hasLocal&&hasExternal)return {action:'receive',eyebrow:'SIGUIENTE PASO',title:'Actualizar separaciones y llegadas',description:'Indicá lo que ya separaste dentro del local y lo que llegó desde proveedor u otro local.',label:'Actualizar cantidades'};
    return {action:'receive',eyebrow:'SIGUIENTE PASO',title:r.estado==='buscando'?'Registrar la mercadería cuando llegue':'Actualizar lo recibido y separado',description:'Cargá únicamente las unidades que ya llegaron y están físicamente separadas para esta reserva.',label:'Registrar llegada y separación'};
  }
  function nextStepMarkup(r,items){const step=nextStep(r,items);return step?`<section class="next-step"><span class="eyebrow">${html(step.eyebrow)}</span><div class="next-step-copy"><h2>${html(step.title)}</h2><p>${html(step.description)}</p></div><button class="button primary" type="button" data-next-step="${html(step.action)}">${html(step.label)} <span aria-hidden="true">→</span></button></section>`:'';}
  function printShortcutMarkup(){return '<section class="print-shortcut"><div><strong>Etiqueta QR</strong><span>Imprimila cuando necesites identificar la mercadería. El QR muestra el estado, las unidades disponibles y las pendientes.</span></div><button class="button secondary" data-detail-action="print" type="button">Imprimir etiqueta</button></section>';}
  function adminActionsMarkup(r){
    if(!isAdmin())return '';
    const closed=E.isTerminal(r.estado),deliveryCorrection=closed||r.estado==='parcial';
    return `<section class="admin-reservation-actions"><div><span class="eyebrow">ADMINISTRACIÓN</span><h2>${closed?'Reserva cerrada':'Correcciones administrativas'}</h2><p>${closed?'Podés reabrirla si el cierre fue incorrecto o eliminarla conservando una copia de auditoría.':'Retrocedé el estado si el proceso fue marcado por error o eliminá una carga inválida.'}</p></div><div class="admin-action-buttons">${deliveryCorrection?'<button class="button warning small" data-detail-action="correct-close" type="button">Reabrir o corregir entrega</button>':'<button class="button secondary small" data-detail-action="progress" type="button">Retroceder o corregir estado</button>'}<button class="button danger small" data-detail-action="delete" type="button">Eliminar reserva</button></div></section>`;
  }
  function renderDetail(){
    const {reservation:r,items,comments,events}=state.current,d=E.deadlineInfo(r.vencimiento_at),terminal=E.isTerminal(r.estado);
    const products=items.map(i=>{
      const extra=[i.fecha_estimada?`Estimado ${html(i.fecha_estimada)}`:'',i.remito_actual||i.remito_numero?`Remito ${html(i.remito_actual||i.remito_numero)}`:'',i.comentario?html(i.comentario):''].filter(Boolean).join(' · ');
      const editLabel=i.procedencia==='local'?'Nota del producto':i.procedencia==='proveedor'?'Llegada, remito y nota':'Preparación y traslado';
      return `<div class="product-line"><div class="product-line-head"><div><strong>${html(i.nombre)}</strong><small>${html(i.codigo)} · ${html(itemOriginLabel(i))}${i.pedido_id?` · Pedido #${html(i.pedido_id.slice(-8,-2).toUpperCase())}`:''}</small></div><span class="badge ${i.estado}">${html(itemStatusLabel(i,r.estado))}</span></div>${itemProcessMarkup(i)}<div class="item-update"><label class="field item-local-field"><span>Unidades separadas aquí</span><input class="input item-local" type="number" min="0" max="${Math.max(0,i.cantidad-i.cantidad_entregada)}" value="${i.cantidad_local}" data-item="${i.id}" ${terminal?'disabled':''}><small>Solo las que están físicamente juntas en el local de destino.</small></label><div class="item-totals"><div class="data-row"><span>Solicitadas</span><strong>${i.cantidad}</strong></div><div class="data-row"><span>Ya entregadas</span><strong>${i.cantidad_entregada}</strong></div></div>${terminal?'':`<button class="button secondary small" type="button" data-save-item="${i.id}">Guardar cantidad</button>`}</div>${extra?`<small>${extra}</small>`:''}<div class="product-actions">${terminal?'':`<button class="button secondary small" type="button" data-edit-item="${i.id}">${editLabel}</button>`}${i.pedido_id?`<a class="button secondary small" href="/?module=pedidos&pedido=${i.pedido_id}">Abrir pedido entre locales</a>`:''}</div></div>`;
    }).join('');
    const commentsHtml=comments.length?comments.map(c=>`<div class="comment"><strong>${html(c.autor_nombre)}</strong>${html(c.texto)}<br><time>${fmt(c.created_at)}</time></div>`).join(''):'<div class="empty">Todavía no hay comentarios.</div>';
    const eventsHtml=events.slice(0,20).map(e=>`<div class="event"><strong>${html(eventLabel(e))}</strong><span>${html(e.autor_nombre)} · ${fmt(e.created_at)}</span></div>`).join('');
    const client=E.customer(r),purpose=purposeLabels[r.finalidad]||r.motivo_nombre||'Reserva',delivery=r.finalidad==='pedido_web'?(deliveryLabels[r.entrega_tipo]||'Entrega a definir'):'';
    $('detail-content').innerHTML=`<div class="detail-hero"><span class="eyebrow">RESERVA #${html(reservationNumber(r))}</span><h1>${html(client)}</h1><div class="detail-meta">${html(r.local_nombre)} · ${html(purpose)}${delivery?` · ${html(delivery)}`:''} · Responsable: ${html(r.responsable_nombre)}</div></div>${r.estado==='vencido'?`<div class="detail-alert"><strong>Superó el plazo de 48 horas.</strong> La mercadería debe volver a exhibición o se debe registrar una excepción.</div>`:''}${nextStepMarkup(r,items)}${printShortcutMarkup()}${adminActionsMarkup(r)}${terminal?'':`<details class="more-actions"><summary>Más acciones</summary><div class="action-bar"><button class="button secondary small" data-detail-action="edit" type="button">Editar reserva</button><button class="button secondary small" data-detail-action="finish" type="button">Entrega o cierre</button>${r.estado==='vencido'?'<button class="button warning small" data-detail-action="exception" type="button">Crear excepción</button>':''}<button class="button danger small" data-detail-action="cancel" type="button">Cancelar</button></div></details>`}<div class="detail-grid"><section class="detail-section"><h2>Datos</h2><div class="data-list"><div class="data-row"><span>Estado</span><strong>${html(E.labels[r.estado]||r.estado)}</strong></div><div class="data-row"><span>Destino</span><strong>${html(purpose)}${delivery?` · ${html(delivery)}`:''}</strong></div><div class="data-row"><span>Teléfono</span><strong>${html(r.cliente_telefono||'—')}</strong></div><div class="data-row"><span>Dirección</span><strong>${html(r.cliente_direccion||'—')}</strong></div><div class="data-row"><span>Ubicación en tienda</span><strong>${html(state.configs[r.local_nombre]?.ubicacion_reservas||'Consultar al responsable')}</strong></div><div class="data-row"><span>Referencia</span><strong>${html(r.referencia_externa||'—')}</strong></div><div class="data-row"><span>Creada</span><strong>${fmt(r.created_at)}</strong></div><div class="data-row"><span>Mercadería desde</span><strong>${fmt(r.mercaderia_local_at)}</strong></div><div class="data-row"><span>Plazo</span><strong class="deadline ${d.kind==='late'?'late':''}">${html(d.label)}</strong></div></div></section><section class="detail-section"><h2>Observaciones generales</h2><p>${html(r.motivo_comentario||'Sin comentario inicial.')}</p>${r.final_tipo?`<p><strong>Resultado:</strong> ${html(E.outcomes[r.final_tipo]||r.final_tipo)}${r.final_comentario?' · '+html(r.final_comentario):''}</p>`:''}</section><section class="detail-section full"><h2>Productos</h2><p class="section-help">Cada línea diferencia lo separado en origen de lo recibido en este local. Solo las unidades físicamente aquí inician el plazo de 48 horas.</p>${products}</section><section class="detail-section"><h2>Comentarios internos</h2>${terminal?'':`<div class="comment-form"><input class="input" id="detail-comment" maxlength="1000" placeholder="Agregar información para el equipo…"><button class="button primary small" data-add-comment type="button">Agregar</button></div>`}<div id="comments-list">${commentsHtml}</div></section><section class="detail-section"><h2>Historial</h2><div class="timeline">${eventsHtml}</div></section></div>`;
    state.detailSignature=JSON.stringify(state.current);
  }
  function eventLabel(e){const map={crear:'Reserva creada',editar:'Reserva editada',estado_automatico:'Estado actualizado automáticamente',cambiar_estado:'Estado actualizado',retroceder_estado:'Estado corregido',actualizar_producto:'Producto actualizado',vencimiento:'Plazo de reserva vencido',excepcion:'Excepción registrada',entrega_parcial:'Entrega parcial',finalizar:'Proceso finalizado',cancelar:'Reserva cancelada',corregir_cierre:'Cierre o entrega corregidos',generar_qr:'Etiqueta QR generada',sincronizar_pedido:'Pedido entre locales sincronizado',vincular_pedido:'Pedido existente vinculado',vincular_remito:'Remito vinculado',recibir_remito:'Mercadería recibida por remito'};return map[e.accion]||e.accion;}
  function closeDetail(){$('detail-modal').hidden=true;state.current=null;state.detailSignature=null;state.detailRequest++;}
  function closeAction(){$('action-modal').hidden=true;$('action-content').innerHTML='';}

  function resetForm(){
    state.editingId=null;state.orderCandidates=[];state.orderCandidatesLocal=null;
    state.newItems=[];['new-reference','new-reason-comment','customer-id','customer-name','customer-surname','customer-phone','customer-document','customer-address','customer-search','product-search'].forEach(id=>{if($(id))$(id).value='';});
    setProductSearchType('nombre',false);ensureProductCatalog().catch(error=>console.warn('[Reservas] No se pudo precargar el padrón de productos.',error));
    $('form-title').textContent=state.publicCreate?`Crear reserva para ${state.actor?.local||'el local'}`:'Crear reserva';$('form-subtitle').textContent='Completá los datos del destinatario y agregá toda la mercadería reservada.';$('create-button').textContent='Crear reserva';
    $('new-responsible').value=state.publicCreate?'':state.actor?.name||'';$('new-purpose').value='retiro_cliente';$('new-web-delivery').value='retiro_local';if(state.actor?.local)$('new-local').value=state.actor.local;syncPurposeFields();renderNewItems();$('new-error').textContent='';
  }
  function syncPurposeFields(){
    const purpose=$('new-purpose').value,web=purpose==='pedido_web',delivery=$('new-web-delivery').value;
    $('web-delivery-field').hidden=!web;$('reference-label').textContent=web?'Número de pedido web *':'Referencia (opcional)';$('new-reference').placeholder=web?'Ej.: WEB-15482':'Ticket, comprobante o referencia interna';$('new-reference').required=web;
    const needsAddress=purpose==='reparto'||(web&&delivery!=='retiro_local');$('customer-address').required=needsAddress;
    const hints={retiro_cliente:'Proceso: separar y etiquetar; cuando todo esté listo, avisar al cliente y registrar el retiro.',reparto:'Proceso: separar y etiquetar; cuando esté completo, asignarlo al reparto y registrar la salida.',pedido_web:`Proceso: identificar con el número web, separar exclusivamente para ese pedido y completar por ${deliveryLabels[delivery]||'el medio elegido'}.`,traslado_interno:'Proceso: indicar el local de destino y el traslado en cada producto; no hace falta completar un cliente si es movimiento interno.',otro:'Describí el destino y el cierre esperado en Observaciones.'};
    $('purpose-hint').textContent=hints[purpose]||hints.otro;
  }
  function setProductSearchType(type,focus=true){
    if(!['nombre','codigo','barras'].includes(type))type='nombre';state.productSearchType=type;
    document.querySelectorAll('[data-product-search-type]').forEach(button=>button.classList.toggle('active',button.dataset.productSearchType===type));
    const input=$('product-search'),panel=$('product-results'),help=$('product-search-help');if(!input)return;
    input.className=type==='barras'?'input barcode':'input';input.placeholder=type==='barras'?'Escanear código de barras...':type==='codigo'?'Buscar por código interno...':'Ej: bio cach med, royal pup 15…';input.inputMode=type==='nombre'?'search':'text';input.value='';panel.hidden=true;
    help.textContent=type==='barras'?'Escaneá el código y presioná Enter.':type==='codigo'?'Busca coincidencias exactas, por comienzo o por parte del código.':'✨ Acepta palabras parciales, en cualquier orden y pequeños errores de escritura.';
    if(focus)input.focus({preventScroll:true});
  }
  async function ensureProductCatalog(){
    if(state.productCatalog)return state.productCatalog;
    if(!state.productCatalogPromise)state.productCatalogPromise=fetch('/products.json',{cache:'no-store'}).then(response=>{if(!response.ok)throw new Error('No se pudo cargar el padrón de productos.');return response.json();}).then(rows=>{
      const seen=new Set();state.productCatalog=(Array.isArray(rows)?rows:[]).filter(product=>{const code=clean(product?.codigo,80);if(!code||seen.has(code))return false;seen.add(code);return true;});state.productSearchIndex=window.SucaneitorSearch?.createSearchIndex(state.productCatalog)||[];return state.productCatalog;
    }).catch(error=>{state.productCatalogPromise=null;throw error;});
    return state.productCatalogPromise;
  }
  function rankProductCatalog(products,index,q,type,limit=32){
    const S=window.SucaneitorSearch;
    if(S&&type==='nombre')return S.rankProducts(index,q,null,limit);
    if(S&&type==='codigo')return S.searchByCode(index,q,limit);
    const normalized=S?.normalizeText(q)||q.toLocaleLowerCase('es').trim(),entries=index.length?index:(products||[]).map((product,order)=>({product,order,codeNorm:String(product.codigo||'').toLocaleLowerCase('es'),barcodeNorm:String(product.barras||'').toLocaleLowerCase('es'),searchableNorm:[product.nombre,product.marca,product.fabricante].filter(Boolean).join(' ').toLocaleLowerCase('es')}));
    const field=type==='barras'?'barcodeNorm':type==='codigo'?'codeNorm':'searchableNorm';
    return entries.filter(entry=>String(entry[field]||'').includes(normalized)).sort((a,b)=>{const av=String(a[field]||''),bv=String(b[field]||''),ar=av===normalized?0:av.startsWith(normalized)?1:2,br=bv===normalized?0:bv.startsWith(normalized)?1:2;return ar-br||av.length-bv.length||a.order-b.order;}).slice(0,limit).map(entry=>({product:entry.product,score:0,reasons:[]}));
  }
  function mergeProductResults(...groups){
    const found=[],seen=new Set();groups.flat().sort((a,b)=>(b.score||0)-(a.score||0)).forEach(result=>{const product=result.product||result,code=String(product?.codigo||'');if(!code||seen.has(code))return;seen.add(code);found.push(result.product?result:{product,score:0,reasons:[]});});return found.slice(0,32);
  }
  function renderProductResults(results){
    const panel=$('product-results'),rows=results.map(result=>result.product||result);panel._rows=rows;
    panel.innerHTML=rows.length?`<div class="product-results-head"><strong>${rows.length===1?'1 resultado':rows.length+' resultados'}</strong><small>Elegí el producto para agregarlo</small></div>`+rows.map((product,index)=>`<button class="result inventory-result" type="button" data-product-index="${index}"><span><strong>${html(product.nombre)}</strong><small>${html(product.codigo)}${product.marca?' · '+html(product.marca):''}${product.barras?' · '+html(product.barras):''}</small></span><b>Elegir</b></button>`).join(''):`<div class="inventory-search-empty"><strong>Sin coincidencias</strong><small>Probá con otras palabras o agregalo manualmente.</small><button class="button secondary small" type="button" data-custom-product>Agregar manualmente</button></div>`;panel.hidden=false;
  }
  async function searchProducts(){
    const q=clean($('product-search').value,100),type=state.productSearchType,request=++state.productSearchRequest,panel=$('product-results');if(q.length<(type==='barras'?1:2)){panel.hidden=true;return;}
    try{
      const catalog=await ensureProductCatalog();if(request!==state.productSearchRequest)return;
      let results=rankProductCatalog(catalog,state.productSearchIndex,q,type);renderProductResults(results);
      try{const remote=await rpc('op_reserva_buscar_productos',withAccess({p_consulta:q}));if(request!==state.productSearchRequest)return;const remoteRows=Array.isArray(remote)?remote:[],remoteIndex=window.SucaneitorSearch?.createSearchIndex(remoteRows)||[];results=mergeProductResults(rankProductCatalog(remoteRows,remoteIndex,q,type),results);renderProductResults(results);}catch(error){console.warn('[Reservas] La búsqueda remota no respondió; se mantiene el padrón local.',error);}
    }catch(error){if(request===state.productSearchRequest)fail(error);}
  }
  async function onProductSearchKeydown(event){
    if(event.key==='Escape'){state.productSearchRequest++;$('product-results').hidden=true;return;}
    if(event.key==='ArrowDown'&&!$('product-results').hidden){event.preventDefault();$('product-results').querySelector('[data-product-index]')?.focus();return;}
    if(event.key!=='Enter')return;event.preventDefault();const value=clean(event.currentTarget.value,100);if(!value)return;
    await searchProducts();if(state.productSearchType!=='barras')return;const rows=$('product-results')._rows||[],normalized=window.SucaneitorSearch?.normalizeText(value)||value.toLocaleLowerCase('es').trim(),exact=rows.filter(product=>(window.SucaneitorSearch?.normalizeText(product.barras)||String(product.barras||'').toLocaleLowerCase('es').trim())===normalized);if(exact.length===1)addProduct(exact[0]);
  }
  async function searchCustomers(){const q=clean($('customer-search').value,100),panel=$('customer-results');if(q.length<2){panel.hidden=true;return;}try{const rows=await rpc('op_reserva_buscar_clientes',withAccess({p_consulta:q}));panel.innerHTML=rows.length?rows.map((c,i)=>`<button class="result" type="button" data-customer-index="${i}"><span><strong>${html([c.nombre,c.apellido].filter(Boolean).join(' '))}</strong><small>${html(c.telefono||'Sin teléfono')}${c.direccion?' · '+html(c.direccion):''}</small></span><b>Elegir</b></button>`).join(''):'<div class="result"><span><strong>Sin coincidencias</strong><small>Los datos ingresados se guardarán al crear.</small></span></div>';panel._rows=rows;panel.hidden=false;}catch(error){fail(error);}}
  function selectCustomer(c){$('customer-id').value=c.id||'';$('customer-name').value=c.nombre||'';$('customer-surname').value=c.apellido||'';$('customer-phone').value=c.telefono||'';$('customer-document').value=c.documento||'';$('customer-address').value=c.direccion||'';$('customer-search').value=[c.nombre,c.apellido,c.telefono].filter(Boolean).join(' · ');$('customer-results').hidden=true;}
  async function loadExistingOrders(){const local=$('new-local').value;if(state.orderCandidatesLocal===local)return;try{state.orderCandidates=await rpc('op_reserva_pedidos_candidatos',withAccess({p_local:local,p_consulta:''}))||[];state.orderCandidatesLocal=local;renderNewItems();}catch(error){fail(error);}}
  function newItem(p,quantity=1){return {key:crypto.randomUUID?.()||String(Date.now()+Math.random()),codigo:clean(p.codigo,80),nombre:clean(p.nombre,240),cantidad:quantity,cantidad_local:0,cantidad_origen:0,procedencia:'local',separacion_estado:'',origen_local:'',proveedor_nombre:'',pedido_local_gestion:'crear',pedido_existente_id:'',traslado_tipo:'reposicion',traslado_detalle:'',tracking:'',fecha_estimada:'',remito_numero:'',comentario:''};}
  function addProduct(p){const existing=state.newItems.find(x=>x.codigo===p.codigo&&x.procedencia==='local');if(existing){existing.cantidad++;if(existing.separacion_estado==='completa')existing.cantidad_local=existing.cantidad;}else state.newItems.push(newItem(p));$('product-search').value='';$('product-results').hidden=true;renderNewItems();}
  function splitItem(index){const item=state.newItems[index];if(!item)return;if(item.cantidad<2)return toast('Para dividir el origen, primero indicá una cantidad de al menos 2.','error');item.cantidad--;item.cantidad_local=Math.min(item.cantidad_local,item.cantidad);state.newItems.splice(index+1,0,newItem(item,1));renderNewItems();}
  function providerOptions(){const local=$('new-local').value;return [...new Set(state.receptionSchedules.filter(x=>x.local_nombre===local&&x.origen_tipo==='proveedor'&&x.activo).map(x=>x.origen_nombre))];}
  function existingOrderOptions(item){const rows=[...state.orderCandidates];if(item.pedido_existente_id&&!rows.some(x=>x.id===item.pedido_existente_id))rows.unshift({id:item.pedido_existente_id,origen_local:item.origen_local,productos:[]});return '<option value="">Elegí un pedido…</option>'+rows.filter(o=>!o.productos?.length||o.productos.some(p=>p.codigo===item.codigo)).map(o=>`<option value="${o.id}" ${o.id===item.pedido_existente_id?'selected':''}>#${html(o.id.slice(-8,-2).toUpperCase())} · ${html(o.origen_local)}</option>`).join('');}
  function renderNewItems(){
    const target=$('new-items');if(!state.newItems.length){target.innerHTML='<div class="empty">Buscá un producto para comenzar.</div>';return;}
    const origins=state.locals.filter(l=>l.nombre!==$('new-local').value),providers=providerOptions();
    target.innerHTML=state.newItems.map((i,index)=>{
      const providerList=`providers-${index}`;
      const separation=i.procedencia==='local'?`<label class="field separation-field"><span>Situación física *</span><select class="input" data-item-field="separacion_estado" required><option value="" ${!i.separacion_estado?'selected':''}>Elegí una opción…</option><option value="pendiente" ${i.separacion_estado==='pendiente'?'selected':''}>Está en el local, falta separarlo</option><option value="completa" ${i.separacion_estado==='completa'?'selected':''}>Ya está separado para esta reserva</option>${i.cantidad>1?`<option value="parcial" ${i.separacion_estado==='parcial'?'selected':''}>Está separado parcialmente</option>`:''}</select><small>Separado significa fuera de góndola o depósito general e identificado para esta reserva.</small></label>${i.separacion_estado==='parcial'?`<label class="field"><span>Unidades ya separadas</span><input class="input" type="number" min="1" max="${Math.max(1,i.cantidad-1)}" value="${i.cantidad_local}" data-item-field="cantidad_local"></label>`:''}`:`<label class="field"><span>Unidades ya recibidas y separadas aquí</span><input class="input" type="number" min="0" max="${i.cantidad}" value="${i.cantidad_local}" data-item-field="cantidad_local"><small>Dejá 0 si todavía están en proveedor, tránsito u otro local.</small></label>`;
      const base=`<label class="field"><span>Cantidad reservada</span><input class="input" type="number" min="1" max="999999" value="${i.cantidad}" data-item-field="cantidad"></label><label class="field source-field"><span>Origen de la mercadería</span><select class="input" data-item-field="procedencia">${Object.entries(sourceLabels).map(([value,label])=>`<option value="${value}" ${value===i.procedencia?'selected':''}>${html(label)}</option>`).join('')}</select></label>${separation}`;
      const provider=i.procedencia==='proveedor'?`<label class="field"><span>Proveedor *</span><input class="input" list="${providerList}" maxlength="120" value="${html(i.proveedor_nombre)}" data-item-field="proveedor_nombre" placeholder="Nombre del proveedor"><datalist id="${providerList}">${providers.map(p=>`<option value="${html(p)}"></option>`).join('')}</datalist></label><label class="field"><span>Fecha estimada (si está confirmada)</span><input class="input" type="date" value="${html(i.fecha_estimada)}" data-item-field="fecha_estimada"></label><label class="field"><span>Remito o comprobante</span><input class="input" maxlength="100" value="${html(i.remito_numero)}" data-item-field="remito_numero"></label>`:'';
      const transfer=i.procedencia==='pedido_local'?`<label class="field"><span>Local de origen *</span><select class="input" data-item-field="origen_local"><option value="">Seleccioná un local…</option>${origins.map(l=>`<option value="${html(l.nombre)}" ${l.nombre===i.origen_local?'selected':''}>${html(l.nombre)} (${html(l.almacen)})</option>`).join('')}</select></label><label class="field"><span>Registro del pedido *</span><select class="input" data-item-field="pedido_local_gestion">${Object.entries(managementLabels).map(([value,label])=>`<option value="${value}" ${value===i.pedido_local_gestion?'selected':''}>${html(label)}</option>`).join('')}</select></label>${i.pedido_local_gestion==='existente'?`<label class="field"><span>Pedido existente *</span><select class="input" data-item-field="pedido_existente_id">${existingOrderOptions(i)}</select></label>`:''}<label class="field"><span>Cómo llegará *</span><select class="input" data-item-field="traslado_tipo">${Object.entries(transportLabels).map(([value,label])=>`<option value="${value}" ${value===i.traslado_tipo?'selected':''}>${html(label)}</option>`).join('')}</select></label>${i.pedido_local_gestion==='externo'?`<label class="field"><span>Separadas en el local de origen</span><input class="input" type="number" min="0" max="${i.cantidad}" value="${i.cantidad_origen}" data-item-field="cantidad_origen"></label>`:''}${['agencia','propio'].includes(i.traslado_tipo)?`<label class="field"><span>${i.traslado_tipo==='agencia'?'Agencia o transporte':'Responsable o vehículo'}</span><input class="input" maxlength="120" value="${html(i.traslado_detalle)}" data-item-field="traslado_detalle" placeholder="Puede completarse al despachar"></label>`:''}<label class="field"><span>Fecha estimada (opcional)</span><input class="input" type="date" value="${html(i.fecha_estimada)}" data-item-field="fecha_estimada"></label>${i.traslado_tipo==='agencia'?`<label class="field"><span>Seguimiento (opcional)</span><input class="input" maxlength="120" value="${html(i.tracking)}" data-item-field="tracking"></label>`:''}<label class="field"><span>Remito interno (opcional)</span><input class="input" maxlength="100" value="${html(i.remito_numero)}" data-item-field="remito_numero"></label>`:'';
      return `<article class="item-editor" data-key="${i.key}"><div class="item-head"><div><strong>${html(i.nombre)}</strong><small>${html(i.codigo)}</small></div><div class="item-head-actions"><button class="button secondary small" type="button" data-split-item="${index}">Dividir origen</button><button class="icon-button" type="button" data-remove-item="${index}" aria-label="Quitar">×</button></div></div><div class="item-fields">${base}${provider}${transfer}<label class="field full"><span>Observaciones del producto</span><input class="input" maxlength="500" value="${html(i.comentario)}" data-item-field="comentario"></label><p class="arrival-hint full">${html(receptionHint(i))}</p></div></article>`;
    }).join('');
  }
  function syncItemField(input){const card=input.closest('[data-key]'),item=state.newItems.find(x=>x.key===card.dataset.key);if(!item)return;const key=input.dataset.itemField;item[key]=key.startsWith('cantidad')?Math.max(0,parseInt(input.value,10)||0):input.value;if(key==='cantidad'){item.cantidad=Math.max(1,item.cantidad);item.cantidad_origen=Math.min(item.cantidad_origen,item.cantidad);if(item.separacion_estado==='completa')item.cantidad_local=item.cantidad;else if(item.separacion_estado==='pendiente')item.cantidad_local=0;else{item.cantidad_local=Math.min(item.cantidad_local,item.cantidad);if(item.cantidad===1&&item.separacion_estado==='parcial'){item.separacion_estado='';item.cantidad_local=0;}}}if(key==='separacion_estado'){if(item.separacion_estado==='completa')item.cantidad_local=item.cantidad;else if(item.separacion_estado==='pendiente'||!item.separacion_estado)item.cantidad_local=0;else if(item.separacion_estado==='parcial')item.cantidad_local=Math.min(Math.max(1,item.cantidad_local||1),Math.max(1,item.cantidad-1));}if(key==='procedencia'){item.cantidad_local=0;item.separacion_estado='';item.origen_local='';item.proveedor_nombre='';item.pedido_local_gestion='crear';item.pedido_existente_id='';item.cantidad_origen=0;item.traslado_tipo='reposicion';item.traslado_detalle='';item.tracking='';item.fecha_estimada='';item.remito_numero='';if(item.procedencia==='pedido_local')loadExistingOrders();}if(key==='pedido_local_gestion'){item.pedido_existente_id='';if(item.pedido_local_gestion!=='externo')item.cantidad_origen=0;}if(key==='traslado_tipo'&&!['agencia','propio'].includes(item.traslado_tipo))item.traslado_detalle='';if(key==='traslado_tipo'&&item.traslado_tipo!=='agencia')item.tracking='';if(key==='pedido_existente_id'){const order=state.orderCandidates.find(x=>x.id===item.pedido_existente_id);if(order)item.origen_local=order.origen_local;}renderNewItems();}

  async function createReservation(event){
    event.preventDefault();const button=$('create-button');$('new-error').textContent='';
    const local=$('new-local').value,responsible=clean($('new-responsible').value,80),finalidad=$('new-purpose').value,entregaTipo=finalidad==='pedido_web'?$('new-web-delivery').value:finalidad==='reparto'?'reparto_local':finalidad==='retiro_cliente'?'retiro_local':null,reference=clean($('new-reference').value,120),address=clean($('customer-address').value,240);
    if(!local||responsible.length<2||!state.newItems.length){$('new-error').textContent='Completá local, responsable y al menos un producto.';return;}
    if(finalidad==='pedido_web'&&!reference){$('new-error').textContent='Ingresá el número del pedido web.';return;}if((finalidad==='reparto'||(finalidad==='pedido_web'&&entregaTipo!=='retiro_local'))&&!address){$('new-error').textContent='Ingresá la dirección de entrega.';return;}
    const invalid=state.newItems.find(i=>i.cantidad<1||i.cantidad_local>i.cantidad||i.cantidad_origen>i.cantidad);if(invalid){$('new-error').textContent='Revisá las cantidades de los productos.';return;}const missingSeparation=state.newItems.find(i=>i.procedencia==='local'&&!['pendiente','completa','parcial'].includes(i.separacion_estado));if(missingSeparation){$('new-error').textContent=`Indicá si ${missingSeparation.nombre} ya quedó separado físicamente.`;return;}const invalidPartial=state.newItems.find(i=>i.procedencia==='local'&&i.separacion_estado==='parcial'&&(i.cantidad_local<1||i.cantidad_local>=i.cantidad));if(invalidPartial){$('new-error').textContent=`Revisá cuántas unidades de ${invalidPartial.nombre} están separadas.`;return;}const missingProvider=state.newItems.find(i=>i.procedencia==='proveedor'&&!clean(i.proveedor_nombre,120));if(missingProvider){$('new-error').textContent=`Indicá el proveedor de ${missingProvider.nombre}.`;return;}const missingOrigin=state.newItems.find(i=>i.procedencia==='pedido_local'&&!i.origen_local);if(missingOrigin){$('new-error').textContent=`Elegí el local que envía ${missingOrigin.nombre}.`;return;}const missingOrder=state.newItems.find(i=>i.procedencia==='pedido_local'&&i.pedido_local_gestion==='existente'&&!i.pedido_existente_id);if(missingOrder){$('new-error').textContent=`Elegí el pedido existente para ${missingOrder.nombre}.`;return;}
    const items=state.newItems.map(i=>({...i,proveedor_nombre:i.procedencia==='proveedor'?clean(i.proveedor_nombre,120):'',origen_local:i.procedencia==='pedido_local'?i.origen_local:'',pedido_local_gestion:i.procedencia==='pedido_local'?i.pedido_local_gestion:null,pedido_existente_id:i.procedencia==='pedido_local'&&i.pedido_local_gestion==='existente'?i.pedido_existente_id:null,traslado_tipo:i.procedencia==='pedido_local'?i.traslado_tipo:null,traslado_detalle:i.procedencia==='pedido_local'?clean(i.traslado_detalle,120):'',tracking:i.procedencia==='pedido_local'?clean(i.tracking,120):'',cantidad_origen:i.procedencia==='pedido_local'&&i.pedido_local_gestion==='externo'?i.cantidad_origen:0,fecha_estimada:i.procedencia==='local'?'':i.fecha_estimada,remito_numero:i.procedencia==='local'?'':i.remito_numero}));
    const payload={local,finalidad,entrega_tipo:entregaTipo,motivo_comentario:clean($('new-reason-comment').value),responsable:responsible,referencia_externa:reference,cliente:{id:$('customer-id').value||null,nombre:clean($('customer-name').value,120),apellido:clean($('customer-surname').value,120),telefono:clean($('customer-phone').value,40),direccion:address,documento:clean($('customer-document').value,50)},items};
    const editing=state.editingId;setBusy(button,true,editing?'Guardando cambios…':'Creando reserva…');try{if(editing){const detail=await rpc('op_reserva_editar',withAccess({p_reserva:editing,p_datos:payload}));resetForm();showView('active');state.current=detail;$('detail-modal').hidden=false;renderDetail();toast('Reserva editada.');}else{const result=await rpc('op_reserva_crear_v2',withAccess({p_datos:payload}));state.qrTokens.set(result.id,result.qr_token);const hasLocalStock=items.some(item=>item.cantidad_local>0);if(state.publicCreate){const fallback={id:result.id,numero:result.number,codigo:result.code,local_nombre:local,local_almacen:localByName(local)?.almacen||'',motivo_nombre:'Reserva',cliente_nombre:payload.cliente.nombre,cliente_apellido:payload.cliente.apellido,cliente_telefono:payload.cliente.telefono,created_at:new Date().toISOString()};state.current={reservation:{...fallback,...(result.label||{}),finalidad:payload.finalidad,entrega_tipo:payload.entrega_tipo,motivo_comentario:payload.motivo_comentario},items:[],comments:[],events:[]};resetForm();showView('new');actionCreated(result,hasLocalStock);}else{resetForm();showView('active');await openDetail(result.id);actionCreated(result,state.current.items.some(item=>item.cantidad_local>0));}}}catch(error){$('new-error').textContent=error.message||'No se pudo guardar la reserva.';}finally{setBusy(button,false);}
  }

  async function saveItem(id){const item=state.current.items.find(x=>x.id===id),input=document.querySelector(`.item-local[data-item="${id}"]`),qty=parseInt(input.value,10),remaining=Math.max(0,item.cantidad-item.cantidad_entregada);if(!Number.isInteger(qty)||qty<0||qty>remaining)return toast('Revisá la cantidad pendiente que está en el local.','error');if(E.needsCorrectionReason(item.cantidad_local,qty)){return actionCorrection(item,qty);}await updateItem(item,qty,'');}
  async function updateItem(item,qty,reason,details={}){const arrived=qty>item.cantidad_local;try{state.current=await rpc('op_reserva_actualizar_item',withAccess({p_item:item.id,p_datos:{cantidad_local:qty,estado:qty+item.cantidad_entregada>=item.cantidad?'separado':qty>0?'recibido':item.estado,motivo_correccion:reason||null,...details}}));renderDetail();await loadList('active',{silent:true});toast('Producto actualizado.');if(arrived)actionMerchandiseArrived(item,qty);}catch(error){fail(error);}}
  function actionCorrection(item,qty){openAction(`<form class="action-form" id="correction-form"><h2>Corregir cantidad</h2><p>Vas a reducir ${html(item.nombre)} de ${item.cantidad_local} a ${qty}. El motivo quedará en el historial.</p><label class="field"><span>Motivo obligatorio</span><textarea class="input" id="correction-reason" maxlength="500" required></textarea></label><button class="button primary" type="submit">Guardar corrección</button></form>`);$('correction-form').onsubmit=async e=>{e.preventDefault();const reason=clean($('correction-reason').value,500);if(reason.length<3)return toast('Explicá el motivo.','error');closeAction();await updateItem(item,qty,reason);};}
  function actionEditItem(id){
    const item=state.current.items.find(x=>x.id===id);if(!item)return;
    if(item.procedencia==='local'){
      openAction(`<form class="action-form" id="item-details-form"><h2>Nota del producto</h2><p>${html(item.nombre)} ya está en este local. No necesita fecha estimada ni remito.</p><label class="field"><span>Comentario</span><textarea class="input" id="item-comment" maxlength="500">${html(item.comentario||'')}</textarea></label><button class="button primary" type="submit">Guardar nota</button></form>`);
      $('item-details-form').onsubmit=async e=>{e.preventDefault();closeAction();await updateItem(item,item.cantidad_local,'',{comentario:clean($('item-comment').value,500),fecha_estimada:'',remito_numero:''});};return;
    }
    if(item.procedencia==='proveedor'){
      openAction(`<form class="action-form" id="item-details-form"><h2>Datos de llegada</h2><p>${html(item.nombre)} · ${html(item.proveedor_nombre||'Proveedor')}</p><label class="field"><span>Fecha estimada (si está confirmada)</span><input class="input" id="item-estimate" type="date" value="${html(item.fecha_estimada||'')}"></label><label class="field"><span>Número de remito</span><input class="input" id="item-receipt" maxlength="100" value="${html(item.remito_numero||'')}"></label><label class="field"><span>Comentario</span><textarea class="input" id="item-comment" maxlength="500">${html(item.comentario||'')}</textarea></label><button class="button primary" type="submit">Guardar datos</button></form>`);
      $('item-details-form').onsubmit=async e=>{e.preventDefault();const details={fecha_estimada:$('item-estimate').value||'',remito_numero:clean($('item-receipt').value,100),comentario:clean($('item-comment').value,500)};closeAction();await updateItem(item,item.cantidad_local,'',details);};return;
    }
    const external=item.pedido_local_gestion==='externo',currentState=item.estado==='en_transito'?'en_transito':preparedAtOrigin(item)>0?'preparado_origen':'pendiente';
    openAction(`<form class="action-form" id="item-details-form"><h2>Preparación y traslado</h2><p>${html(item.nombre)} · ${html(item.origen_local||'Otro local')} → ${html(state.current.reservation.local_nombre)}</p>${external?`<label class="field"><span>Unidades separadas en origen</span><input class="input" id="item-origin-qty" type="number" min="0" max="${item.cantidad}" value="${preparedAtOrigin(item)}"></label><label class="field"><span>Estado del traslado</span><select class="input" id="item-route-state"><option value="pendiente" ${currentState==='pendiente'?'selected':''}>Todavía sin separar</option><option value="preparado_origen" ${currentState==='preparado_origen'?'selected':''}>Separado en el local de origen</option><option value="en_transito" ${currentState==='en_transito'?'selected':''}>Salió y está en tránsito</option></select></label>`:'<p class="form-help">La cantidad preparada y el estado se actualizan desde Pedidos entre locales. Aquí podés corregir solamente el plan y los datos del traslado.</p>'}<label class="field"><span>Cómo llegará</span><select class="input" id="item-transport">${Object.entries(transportLabels).map(([value,label])=>`<option value="${value}" ${(item.traslado_tipo_actual||item.traslado_tipo)===value?'selected':''}>${html(label)}</option>`).join('')}</select></label><label class="field"><span>Agencia, responsable o vehículo</span><input class="input" id="item-transport-detail" maxlength="120" value="${html(item.traslado_actual||item.traslado_detalle||'')}"></label><label class="field"><span>Fecha estimada (opcional)</span><input class="input" id="item-estimate" type="date" value="${html(item.fecha_estimada||'')}"></label><label class="field"><span>Seguimiento (opcional)</span><input class="input" id="item-tracking" maxlength="120" value="${html(item.tracking_actual||item.tracking||'')}"></label><label class="field"><span>Remito interno (opcional)</span><input class="input" id="item-receipt" maxlength="100" value="${html(item.remito_actual||item.remito_numero||'')}"></label><label class="field"><span>Comentario</span><textarea class="input" id="item-comment" maxlength="500">${html(item.comentario||'')}</textarea></label><button class="button primary" type="submit">Guardar seguimiento</button></form>`);
    $('item-details-form').onsubmit=async e=>{e.preventDefault();const details={traslado_tipo:$('item-transport').value,traslado_detalle:clean($('item-transport-detail').value,120),fecha_estimada:$('item-estimate').value||'',tracking:clean($('item-tracking').value,120),remito_numero:clean($('item-receipt').value,100),comentario:clean($('item-comment').value,500)};if(external){details.cantidad_origen=Math.max(0,parseInt($('item-origin-qty').value,10)||0);details.estado=$('item-route-state').value;if(details.estado==='en_transito'&&details.cantidad_origen<1)return toast('Indicá cuántas unidades salieron del local de origen.','error');}closeAction();await updateItem(item,item.cantidad_local,'',details);};
  }
  async function actionLinkOrder(){const r=state.current.reservation;openAction(`<div class="action-form"><h2>Vincular pedido existente</h2><p>Se muestran pedidos destinados a ${html(r.local_nombre)} que coinciden con algún producto pendiente.</p><input class="input" id="order-link-search" type="search" placeholder="Buscar por origen, cliente, código o producto…"><div id="order-link-results" class="order-link-results"><div class="empty">Buscando pedidos…</div></div></div>`);const load=debounce(async()=>{const panel=$('order-link-results');if(!panel)return;panel.innerHTML='<div class="empty">Buscando pedidos…</div>';try{const rows=await rpc('op_reserva_pedidos_disponibles',withAccess({p_reserva:r.id,p_consulta:clean($('order-link-search').value,100)}));panel.innerHTML=rows.length?rows.map(o=>`<button class="order-link-card" type="button" data-link-order="${o.id}"><span><strong>Pedido #${html(o.id.slice(-8,-2).toUpperCase())} · ${html(o.origen_local)}</strong><small>${html(o.cliente||'Sin cliente')} · ${html(o.estado)} · ${fmt(o.created_at)}</small><small>${o.productos.map(p=>`${html(p.nombre)} × ${p.cantidad}`).join(' · ')}</small></span><b>Vincular</b></button>`).join(''):'<div class="empty">No hay pedidos compatibles sin vincular.</div>';}catch(error){panel.innerHTML=`<div class="empty">${html(error.message)}</div>`;}},220);$('order-link-search').addEventListener('input',load);load();}
  async function linkOrder(id){const r=state.current.reservation;try{state.current=await rpc('op_reserva_vincular_pedido',withAccess({p_reserva:r.id,p_pedido:id}));closeAction();renderDetail();await loadList('active');toast('Pedido vinculado a la reserva.');}catch(error){fail(error);}}
  function openAction(markup){$('action-content').innerHTML=markup;$('action-modal').hidden=false;}
  function actionCreated(result,hasLocalStock){const message=hasLocalStock?'La mercadería disponible ya puede identificarse con su etiqueta.':'La reserva quedó guardada y la etiqueta ya se puede imprimir. Colocala cuando separe la primera unidad para que el equipo consulte el estado desde el QR.';actionPrintPrompt(`Reserva #${html(reservationNumber(result))} creada`,message,state.publicCreate?'Crear otra reserva':hasLocalStock?'La etiqueta ya está colocada':'Continuar sin imprimir',trackingUrl(result.qr_token));}
  function beginEditReservation(){const {reservation:r,items}=state.current;closeDetail();state.editingId=r.id;state.newItems=items.map(i=>({key:i.id,id:i.id,codigo:i.codigo,nombre:i.nombre,cantidad:i.cantidad,cantidad_local:i.cantidad_local,cantidad_origen:i.cantidad_origen||0,procedencia:['local','proveedor','pedido_local'].includes(i.procedencia)?i.procedencia:'proveedor',separacion_estado:i.procedencia==='local'?(i.cantidad_local<=0?'pendiente':i.cantidad_local>=i.cantidad?'completa':'parcial'):'',origen_local:i.origen_local||'',proveedor_nombre:i.proveedor_nombre||'',pedido_local_gestion:i.pedido_local_gestion||(i.pedido_id?'existente':'externo'),pedido_existente_id:i.pedido_id||'',traslado_tipo:i.traslado_tipo||'coordinar',traslado_detalle:i.traslado_detalle||'',tracking:i.tracking||'',fecha_estimada:i.procedencia==='local'?'':i.fecha_estimada||'',remito_numero:i.procedencia==='local'?'':i.remito_numero||'',comentario:i.comentario||''}));showView('new');$('form-title').textContent=`Editar reserva #${reservationNumber(r)}`;$('form-subtitle').textContent='Actualizá el destino, los productos o sus recorridos y guardá los cambios.';$('create-button').textContent='Guardar cambios';$('new-local').value=r.local_nombre;$('new-responsible').value=r.responsable_nombre||'';$('new-purpose').value=r.finalidad||'retiro_cliente';$('new-web-delivery').value=r.entrega_tipo||'retiro_local';$('new-reference').value=r.referencia_externa||'';$('new-reason-comment').value=r.motivo_comentario||'';$('customer-id').value=r.cliente_id||'';$('customer-name').value=r.cliente_nombre||'';$('customer-surname').value=r.cliente_apellido||'';$('customer-phone').value=r.cliente_telefono||'';$('customer-document').value=r.cliente_documento||'';$('customer-address').value=r.cliente_direccion||'';syncPurposeFields();state.orderCandidates=items.filter(i=>i.pedido_id).map(i=>({id:i.pedido_id,origen_local:i.origen_local,productos:[{codigo:i.codigo,nombre:i.nombre,cantidad:i.cantidad}]}));state.orderCandidatesLocal=null;if(items.some(i=>i.procedencia==='pedido_local'))loadExistingOrders();renderNewItems();window.scrollTo({top:0,behavior:'smooth'});}
  function cancelReservationForm(){resetForm();showView(state.publicCreate?'new':'active');}
  function actionDelete(){if(!isAdmin())return toast('Solo un administrador puede eliminar reservas.','error');const r=state.current.reservation,reference=reservationNumber(r);openAction(`<form class="action-form" id="delete-form"><h2>Eliminar reserva #${html(reference)}</h2><p>La reserva dejará de aparecer en las listas y la etiqueta QR quedará inactiva. Se conservará una copia completa de auditoría con el motivo y el administrador responsable.</p><label class="field"><span>Escribí ${html(reference)} para confirmar</span><input class="input mono" id="delete-code" autocomplete="off" required></label><label class="field"><span>Motivo obligatorio</span><textarea class="input" id="delete-reason" maxlength="500" required></textarea></label><button class="button danger" type="submit">Eliminar reserva</button></form>`);$('delete-form').onsubmit=async e=>{e.preventDefault();const code=clean($('delete-code').value,20),reason=clean($('delete-reason').value,500);if(code.toUpperCase()!==reference.toUpperCase())return toast('El número de confirmación no coincide.','error');if(reason.length<3)return toast('Explicá por qué se elimina.','error');setBusy(e.submitter,true,'Eliminando…');try{await rpc('op_reserva_eliminar',withAccess({p_reserva:r.id,p_codigo:code,p_motivo:reason}));closeAction();closeDetail();await loadList('active');toast(`Reserva #${reference} eliminada.`);}catch(error){fail(error);setBusy(e.submitter,false);}};}
  function actionMerchandiseArrived(item,qty){const local=item.procedencia==='local';actionPrintPrompt(local?'Separación registrada':'Mercadería recibida y separada',`${html(item.nombre)} tiene ${qty} ${qty===1?'unidad separada':'unidades separadas'}. Imprimí la etiqueta de la reserva si todavía no está colocada.`);}
  function actionPrintPrompt(title,message,skipLabel='La etiqueta ya está colocada',url=''){openAction(`<div class="action-form"><h2>${title}</h2><p>${message} El QR permite identificar al destinatario y consultar todos los productos.</p>${url?`<div class="created-link"><span>Enlace de seguimiento</span><a href="${html(url)}" target="_blank" rel="noopener">${html(url)}</a><button class="button secondary" type="button" data-copy-created-link="${html(url)}">Copiar enlace</button></div>`:''}<button class="button primary" type="button" data-print-created>Imprimir etiqueta</button><button class="button secondary" type="button" data-close-action>${html(skipLabel)}</button></div>`);}
  function showGuide(){const adminHelp=isAdmin()?'<div class="guide-step"><strong>Administrar locales</strong>En Configuración podés definir la ubicación de las reservas, la impresora, los días de recepción y los enlaces de creación.</div>':'';const manageHelp=state.publicCreate?'':'<div class="guide-step"><strong>Completar el proceso</strong>Registrá el aviso al cliente y cerrá la reserva cuando la mercadería se entregue, se envíe o vuelva a exhibición.</div>';openAction(`<section class="guide"><h2>Ayuda de reservas</h2><p class="guide-intro">Cada reserva separa tres datos: para qué se guarda, de dónde sale cada producto y cómo llega.</p><div class="guide-list"><div class="guide-step"><strong>Definir el destino</strong>Indicá si es retiro, reparto, pedido web o traslado interno. Los pedidos web deben llevar su número.</div><div class="guide-step"><strong>Disponible en el local</strong>Indicá si todavía está en góndola o depósito general, si ya fue separado o si solo se apartó una parte. La disponibilidad señala el origen; la situación física indica el avance real.</div><div class="guide-step"><strong>Esperando proveedor</strong>Registrá proveedor y, solo si está confirmada, la fecha. Al recibir, controlá remito y separá.</div><div class="guide-step"><strong>Pedido a otro local</strong>Elegí si se crea, vincula o coordina fuera del sistema; después indicá si viajará en reposición, agencia o traslado propio.</div><div class="guide-step"><strong>Separado en origen no es recibido</strong>En un traslado se controla por separado lo preparado en el local que envía y lo que ya llegó al local de destino.</div><div class="guide-step"><strong>Dividir una cantidad</strong>Usá “Dividir origen” cuando las unidades de un mismo producto provengan de lugares o recorridos distintos.</div><div class="guide-step"><strong>Identificar la mercadería</strong>La etiqueta puede imprimirse desde la creación, el detalle o el enlace QR.</div>${manageHelp}${adminHelp}</div></section>`);}
  function actionAdvanceState(target){
    const r=state.current.reservation,notice=target==='avisado',title=notice?'Confirmar aviso al cliente':'Confirmar mercadería en tránsito',description=notice?'Hacé esta confirmación después de llamar o escribir al cliente. El equipo verá que ya fue avisado.':'Hacé esta confirmación cuando el local de origen informe que la mercadería salió.';
    openAction(`<form class="action-form" id="next-state-form"><h2>${title}</h2><p>${description}</p><label class="field"><span>Comentario opcional</span><textarea class="input" id="next-state-comment" maxlength="500" placeholder="Ej.: cliente avisado / enviado en el reparto de la tarde"></textarea></label><button class="button primary" type="submit">${notice?'Sí, registrar aviso':'Sí, pasar a En tránsito'}</button></form>`);
    $('next-state-form').onsubmit=async e=>{e.preventDefault();setBusy(e.submitter,true,'Guardando…');await runDetailRpc('op_reserva_cambiar_estado',{p_reserva:r.id,p_estado:target,p_comentario:clean($('next-state-comment').value,500)});};
  }
  function actionRegisterArrival(){
    const {items}=state.current,rows=items.filter(item=>item.cantidad_entregada<item.cantidad);
    const localOnly=rows.every(item=>item.procedencia==='local'),externalOnly=rows.every(item=>item.procedencia!=='local');
    const title=localOnly?'Registrar separación':externalOnly?'Registrar llegada y separación':'Actualizar separaciones y llegadas';
    const intro=localOnly?'Anotá cuántas unidades retiraste de góndola o depósito general y dejaste físicamente separadas para esta reserva.':externalOnly?'Anotá cuántas unidades ya llegaron y quedaron físicamente separadas para esta reserva.':'Actualizá tanto lo que separaste dentro del local como lo que llegó desde proveedor u otro local. No cuentes mercadería que siga en góndola o depósito general.';
    const unchanged=localOnly?'Ingresá la cantidad que separaste para continuar.':externalOnly?'Ingresá la cantidad que llegó para continuar.':'Actualizá al menos una cantidad para continuar.';
    const success=localOnly?'Separación registrada. El estado se actualizó automáticamente.':externalOnly?'Llegada registrada. El estado se actualizó automáticamente.':'Cantidades actualizadas. El estado se actualizó automáticamente.';
    openAction(`<form class="action-form" id="arrival-form"><h2>${title}</h2><p>${intro}</p><div class="arrival-list">${rows.map(item=>`<label class="arrival-row"><span><strong>${html(item.nombre)}</strong><small>${html(item.codigo)} · ${item.cantidad} solicitadas · ${item.cantidad_entregada} entregadas</small></span><span class="arrival-qty"><small>${item.procedencia==='local'?'Separadas':'Recibidas aquí'}</small><input class="input next-local-qty" data-id="${item.id}" type="number" min="${item.cantidad_local}" max="${Math.max(0,item.cantidad-item.cantidad_entregada)}" value="${item.cantidad_local}"></span></label>`).join('')}</div><p class="form-help">Al guardar, el estado avanzará automáticamente. Si ya está todo junto, quedará “Lista para entregar”.</p><button class="button primary" type="submit">Guardar y continuar</button></form>`);
    $('arrival-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter,quantities=[...document.querySelectorAll('.next-local-qty')].map(input=>({id:input.dataset.id,qty:parseInt(input.value,10)}));if(quantities.some(entry=>!Number.isInteger(entry.qty)))return toast('Revisá las cantidades.','error');if(!quantities.some(entry=>entry.qty!==state.current.items.find(item=>item.id===entry.id)?.cantidad_local))return toast(unchanged,'error');setBusy(button,true,'Guardando…');let arrived=false;try{for(const entry of quantities){const item=state.current.items.find(row=>row.id===entry.id);if(!item||entry.qty===item.cantidad_local)continue;const maximum=Math.max(0,item.cantidad-item.cantidad_entregada);if(entry.qty<item.cantidad_local||entry.qty>maximum)throw new Error('La cantidad debe estar entre lo ya separado y lo pendiente.');arrived=arrived||entry.qty>item.cantidad_local;state.current=await rpc('op_reserva_actualizar_item',withAccess({p_item:item.id,p_datos:{cantidad_local:entry.qty,estado:entry.qty+item.cantidad_entregada>=item.cantidad?'separado':entry.qty>0?'recibido':item.estado,motivo_correccion:null}}));}closeAction();renderDetail();await loadList('active',{silent:true});toast(success);if(arrived)actionPrintPrompt(localOnly?'Separación registrada':'Mercadería registrada en el local','Las unidades ya figuran separadas. Imprimí la etiqueta de la reserva si todavía no está colocada.');}catch(error){fail(error);setBusy(button,false);}}
  }
  function actionProgress(){const r=state.current.reservation;openAction(`<form class="action-form" id="progress-form"><h2>Cambiar estado</h2><p>Elegí el punto real del proceso. Para retroceder, el comentario es obligatorio.</p><label class="field"><span>Nuevo estado</span><select class="input" id="progress-state">${['buscando','en_transito','recibido','separando','listo','avisado'].map(s=>`<option value="${s}" ${r.estado===s?'selected':''}>${html(E.labels[s])}</option>`).join('')}</select></label><label class="field"><span>Comentario o motivo de corrección</span><textarea class="input" id="progress-comment" maxlength="500"></textarea></label><button class="button primary" type="submit">Guardar estado</button></form>`);$('progress-form').onsubmit=async e=>{e.preventDefault();await runDetailRpc('op_reserva_cambiar_estado',{p_reserva:r.id,p_estado:$('progress-state').value,p_comentario:clean($('progress-comment').value,500)});};}
  function actionFinish(){const {reservation:r,items}=state.current,defaultOutcome=r.finalidad==='traslado_interno'?'envio_otro_local':r.finalidad==='reparto'||(r.finalidad==='pedido_web'&&r.entrega_tipo!=='retiro_local')?'reparto':'retiro_cliente';openAction(`<form class="action-form" id="finish-form"><h2>Entrega o cierre</h2><p>Confirmá qué pasó y las cantidades entregadas o despachadas. Si queda algo pendiente, la reserva continuará abierta.</p><label class="field"><span>Resultado</span><select class="input" id="finish-type">${Object.entries(E.outcomes).map(([v,l])=>`<option value="${v}" ${v===defaultOutcome?'selected':''}>${html(l)}</option>`).join('')}</select></label><div class="delivery-list">${items.map(i=>`<label class="delivery-row"><span>${html(i.nombre)}<small> · ${i.cantidad} solicitadas</small></span><input class="input delivery-qty" data-id="${i.id}" data-current="${i.cantidad_entregada}" data-with-local="${Math.min(i.cantidad,i.cantidad_entregada+i.cantidad_local)}" type="number" min="${i.cantidad_entregada}" max="${i.cantidad}" value="${Math.min(i.cantidad,i.cantidad_entregada+i.cantidad_local)}"></label>`).join('')}</div><p class="form-help" id="finish-help"></p><label class="field"><span>Comentario final</span><textarea class="input" id="finish-comment" maxlength="500"></textarea></label><button class="button primary" type="submit">Confirmar resultado</button></form>`);const syncOutcome=()=>{const returned=$('finish-type').value==='no_retirado';document.querySelectorAll('.delivery-qty').forEach(x=>{x.value=returned?x.dataset.current:x.dataset.withLocal;x.readOnly=returned;});$('finish-help').textContent=returned?'Las unidades no entregadas dejarán de estar reservadas y volverán a exhibición. No se modifica stock.':'';};$('finish-type').addEventListener('change',syncOutcome);syncOutcome();$('finish-form').onsubmit=async e=>{e.preventDefault();const deliveries=[...document.querySelectorAll('.delivery-qty')].map(x=>({id:x.dataset.id,cantidad:parseInt(x.value,10)||0}));await runDetailRpc('op_reserva_finalizar',{p_reserva:r.id,p_tipo:$('finish-type').value,p_entregas:deliveries,p_comentario:clean($('finish-comment').value,500)});};}
  function actionException(){const r=state.current.reservation,until=new Date(Date.now()+24*3600000);until.setMinutes(until.getMinutes()-until.getTimezoneOffset());openAction(`<form class="action-form" id="exception-form"><h2>Crear excepción</h2><p>La reserva volverá al estado anterior hasta la nueva fecha límite.</p><label class="field"><span>Nueva fecha y hora</span><input class="input" id="exception-until" type="datetime-local" value="${until.toISOString().slice(0,16)}" required></label><label class="field"><span>Motivo obligatorio</span><textarea class="input" id="exception-reason" maxlength="500" required></textarea></label><button class="button primary" type="submit">Aplicar excepción</button></form>`);$('exception-form').onsubmit=async e=>{e.preventDefault();await runDetailRpc('op_reserva_excepcion',{p_reserva:r.id,p_hasta:new Date($('exception-until').value).toISOString(),p_motivo:clean($('exception-reason').value,500)});};}
  function actionCancel(){const r=state.current.reservation;openAction(`<form class="action-form" id="cancel-form"><h2>Cancelar reserva</h2><p>No se eliminará: quedará conservada en el historial.</p><label class="field"><span>Motivo obligatorio</span><textarea class="input" id="cancel-reason" maxlength="500" required></textarea></label><button class="button danger" type="submit">Cancelar reserva</button></form>`);$('cancel-form').onsubmit=async e=>{e.preventDefault();await runDetailRpc('op_reserva_cancelar',{p_reserva:r.id,p_motivo:clean($('cancel-reason').value,500)});};}
  function actionCorrectClose(){if(!isAdmin())return toast('Solo un administrador puede reabrir una reserva cerrada.','error');const {reservation:r,items}=state.current,help=r.estado==='cancelado'?'Se restaurarán las cantidades que estaban separadas antes de cancelar. También podés corregir entregas marcadas por error.':'Corregí las cantidades entregadas que se registraron por error. Las unidades descontadas volverán a figurar separadas y la reserva quedará abierta.';openAction(`<form class="action-form" id="correct-close-form"><h2>Reabrir o corregir reserva</h2><p>${help}</p><div class="delivery-list">${items.map(i=>`<label class="delivery-row"><span>${html(i.nombre)}<small> · ${i.cantidad} solicitadas</small></span><input class="input corrected-delivery" data-id="${i.id}" type="number" min="0" max="${i.cantidad_entregada}" value="${i.cantidad_entregada}"></label>`).join('')}</div><label class="field"><span>Motivo obligatorio</span><textarea class="input" id="correct-close-reason" maxlength="500" required></textarea></label><button class="button warning" type="submit">Reabrir y guardar corrección</button></form>`);$('correct-close-form').onsubmit=async e=>{e.preventDefault();const motivo=clean($('correct-close-reason').value,500);if(motivo.length<3)return toast('Explicá el motivo de la corrección.','error');const deliveries=[...document.querySelectorAll('.corrected-delivery')].map(x=>({id:x.dataset.id,cantidad:parseInt(x.value,10)||0}));await runDetailRpc('op_reserva_corregir_cierre',{p_reserva:r.id,p_entregas:deliveries,p_motivo:motivo});};}
  async function runDetailRpc(name,args){try{state.current=await rpc(name,withAccess(args));closeAction();renderDetail();await loadList('active',{silent:true});toast('Reserva actualizada.');}catch(error){fail(error);}}
  async function addComment(){const input=$('detail-comment'),text=clean(input.value);if(!text)return;try{await rpc('op_reserva_comentar',withAccess({p_reserva:state.current.reservation.id,p_texto:text}));state.current=await rpc('op_reserva_detalle',withAccess({p_reserva:state.current.reservation.id}));renderDetail();toast('Comentario agregado.');}catch(error){fail(error);}}

  async function printLabel(){
    const r=state.current.reservation;let token=state.qrTokens.get(r.id)||r.qr_token;
    const win=window.open('','_blank','width=1000,height=560');
    if(!win)return fail(new Error('Permití las ventanas emergentes para imprimir.'));
    win.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Preparando etiqueta…</title></head><body style="font-family:Arial,sans-serif;padding:24px">Preparando etiqueta…</body></html>');win.document.close();
    try{if(!token){const result=await rpc('op_reserva_qr_regenerar',withAccess({p_reserva:r.id}));token=result.token;state.qrTokens.set(r.id,token);}await renderPrintWindow(r,trackingUrl(token),win);}catch(error){if(!win.closed)win.close();fail(error);}
  }
  function qrDataUrl(text){return new Promise((resolve,reject)=>{const box=document.createElement('div');box.style.cssText='position:fixed;left:-10000px;top:0;background:#fff;padding:0';document.body.appendChild(box);new QRCode(box,{text,width:232,height:232,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});setTimeout(()=>{const canvas=box.querySelector('canvas'),img=box.querySelector('img');const url=canvas?.toDataURL('image/png')||img?.src;box.remove();url?resolve(url):reject(new Error('No se pudo generar el QR'));},80);});}
  async function renderPrintWindow(r,url,win){const qr=await qrDataUrl(url);if(win.closed)throw new Error('La ventana de impresión se cerró antes de preparar la etiqueta.');const customer=E.customer(r),phone=r.cliente_telefono||'SIN TELÉFONO',date=new Date(r.created_at).toLocaleDateString('es-UY'),location=state.configs[r.local_nombre]?.ubicacion_reservas,reference=reservationNumber(r),purpose=purposeLabels[r.finalidad]||r.motivo_nombre||'Reserva',delivery=r.finalidad==='pedido_web'?(deliveryLabels[r.entrega_tipo]||'Entrega a definir'):'',reason=`${purpose}${delivery?' · '+delivery:''}`,observations=labelText(r.motivo_comentario);win.document.open();win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Reserva ${html(reference)}</title><style>@page{size:80mm 200mm;margin:0}*{box-sizing:border-box}html{width:80mm;height:200mm;margin:0;padding:0;overflow:hidden;color:#000;background:#fff;font-family:Arial,sans-serif}body{position:relative;width:80mm;height:200mm;margin:0;padding:0;overflow:hidden}.label{position:absolute;top:0;left:79.5mm;width:199mm;height:79mm;margin:0;padding:5mm 8mm;overflow:hidden;transform:rotate(90deg);transform-origin:top left;break-inside:avoid;page-break-inside:avoid;display:grid;grid-template-columns:66mm minmax(0,1fr);gap:9mm;align-items:center}.qr{display:block;width:66mm;height:66mm;image-rendering:pixelated}.copy{min-width:0;max-height:66mm;overflow:hidden;border-left:.5mm solid #000;padding-left:8mm}.code{font:800 15pt monospace;letter-spacing:.35mm}.name{max-height:15mm;overflow:hidden;margin:1.5mm 0 1mm;font-size:22pt;font-weight:900;line-height:1;word-break:break-word}.phone{font-size:14pt;font-weight:800;line-height:1.1}.date{margin-top:1mm;font-size:10pt;font-weight:700}.reason{margin-top:1.4mm;padding-top:1.2mm;border-top:.25mm solid #000;font-size:10pt;font-weight:900;line-height:1.12}.observations{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3;margin-top:1.2mm;font-size:8.5pt;font-weight:700;line-height:1.14;word-break:break-word}.location{margin-top:1.2mm;font-size:8.5pt;font-weight:800;line-height:1.1}.instruction{margin-top:1.4mm;font-size:7.2pt;font-weight:800;letter-spacing:.18mm}@media print{html,body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="label"><img class="qr" src="${qr}" alt="QR de la reserva"><div class="copy"><div class="code">RESERVA #${html(reference)}</div><div class="name">${html(customer)}</div><div class="phone">TEL: ${html(phone)}</div><div class="date">${html(date)} · LOCAL ${html(r.local_almacen)}</div><div class="reason">MOTIVO: ${html(reason)}</div>${observations?`<div class="observations">OBSERVACIONES: ${html(observations)}</div>`:''}${location?`<div class="location">UBICACIÓN: ${html(location)}</div>`:''}<div class="instruction">ESCANEÁ EL QR PARA VER PRODUCTOS Y SEGUIMIENTO</div></div></div><script>onload=()=>{setTimeout(()=>print(),120);onafterprint=()=>close()}<\/script></body></html>`);win.document.close();}

  async function resolveQr(token){try{const result=await rpc('op_reserva_qr_resolver',withAccess({p_token:token}));if(result?.id)await openDetail(result.id);}catch(error){fail(error,'resolve qr');}}

  function renderScheduleType(){const localType=$('schedule-type').value==='local';$('schedule-provider-field').hidden=localType;$('schedule-local-field').hidden=!localType;}
  function resetScheduleForm(){if(!$('schedule-id'))return;$('schedule-id').value='';$('schedule-type').value='proveedor';$('schedule-provider').value='';fillScheduleOriginOptions();$('schedule-origin-local').value='';document.querySelectorAll('.schedule-days input').forEach(x=>x.checked=false);$('save-schedule').textContent='Agregar calendario';$('cancel-schedule-edit').hidden=true;renderScheduleType();}
  function renderSchedules(local){const rows=state.receptionSchedules.filter(x=>x.local_nombre===local),labels=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];$('schedule-list').innerHTML=rows.length?rows.map(row=>`<div class="schedule-row ${row.activo?'':'inactive'}"><div><strong>${row.origen_tipo==='local'?'Local':'Proveedor'} · ${html(row.origen_nombre)}</strong><small>${row.dias_recepcion.length?row.dias_recepcion.map(d=>labels[d]).join(', '):'Sin días configurados'}${row.activo?'':' · Inactivo'}</small></div><div class="settings-actions"><button class="button secondary small" type="button" data-edit-schedule="${row.id}">Editar</button><button class="button ${row.activo?'warning':'secondary'} small" type="button" data-toggle-schedule="${row.id}">${row.activo?'Desactivar':'Reactivar'}</button></div></div>`).join(''):'<div class="empty">Todavía no hay calendarios para este local.</div>';}
  function renderSettings(){if(!isAdmin())return showView('active');const local=$('settings-local').value||state.locals[0]?.nombre;if(!local)return;const config=state.configs[local]||{ubicacion_reservas:'',printer_path:''};$('settings-location').value=config.ubicacion_reservas||'';$('settings-printer').value=config.printer_path||'';resetScheduleForm();renderSchedules(local);renderQuickLink(local);}
  async function refreshContext(){state.context=await rpc('op_reserva_contexto',withAccess());state.reasons=state.context.reasons||[];state.configs=state.context.config||{};state.receptionSchedules=state.context.reception_schedules||[];}
  async function saveSettings(){if(!isAdmin())return;const local=$('settings-local').value,location=clean($('settings-location').value,160),path=clean($('settings-printer').value,240);try{const result=await rpc('op_reserva_guardar_config',{p_local:local,p_horas:48,p_dias:[],p_ubicacion:location||null,p_printer_path:path||null,p_printer_profile:'star-bsc10-80-max'});state.configs[local]=result;toast('Configuración guardada.');}catch(error){fail(error);}}
  async function saveSchedule(){if(!isAdmin())return;const id=$('schedule-id').value||null,local=$('settings-local').value,type=$('schedule-type').value,origin=type==='local'?$('schedule-origin-local').value:clean($('schedule-provider').value,120),days=[...document.querySelectorAll('.schedule-days input:checked')].map(x=>Number(x.value));if(!origin)return toast('Indicá el proveedor o local de origen.','error');if(!days.length)return toast('Elegí al menos un día habitual.','error');try{await rpc('op_reserva_guardar_recepcion_habitual',{p_id:id,p_local:local,p_origen_tipo:type,p_origen_nombre:origin,p_dias:days,p_activo:true});await refreshContext();resetScheduleForm();renderSchedules(local);toast(id?'Calendario actualizado.':'Calendario agregado.');}catch(error){fail(error);}}
  function editSchedule(id){if(!isAdmin())return;const row=state.receptionSchedules.find(x=>x.id===id);if(!row)return;$('schedule-id').value=row.id;$('schedule-type').value=row.origen_tipo;$('schedule-provider').value=row.origen_tipo==='proveedor'?row.origen_nombre:'';fillScheduleOriginOptions();$('schedule-origin-local').value=row.origen_tipo==='local'?row.origen_nombre:'';document.querySelectorAll('.schedule-days input').forEach(x=>x.checked=row.dias_recepcion.includes(Number(x.value)));$('save-schedule').textContent='Guardar calendario';$('cancel-schedule-edit').hidden=false;renderScheduleType();}
  async function toggleSchedule(id){if(!isAdmin())return;const row=state.receptionSchedules.find(x=>x.id===id);if(!row)return;try{await rpc('op_reserva_guardar_recepcion_habitual',{p_id:row.id,p_local:row.local_nombre,p_origen_tipo:row.origen_tipo,p_origen_nombre:row.origen_nombre,p_dias:row.dias_recepcion,p_activo:!row.activo});await refreshContext();renderSchedules($('settings-local').value);toast(row.activo?'Calendario desactivado.':'Calendario reactivado.');}catch(error){fail(error);}}
  async function printCalibration(){
    if(!isAdmin())return;
    let win;
    try{
      if(typeof window.JsBarcode!=='function')throw new Error('No se pudo cargar el generador del código de barras.');
      win=window.open('','_blank','width=540,height=820');if(!win)throw new Error('Permití las ventanas emergentes para imprimir la prueba.');
      win.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Preparando calibración…</title></head><body style="font-family:Arial,sans-serif;padding:24px">Preparando prueba de calibración…</body></html>');win.document.close();
      const qr=await qrDataUrl(`${location.origin}/reserva#BSC10-CALIBRACION`),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');
      window.JsBarcode(svg,'BSC10-203DPI',{format:'CODE128',width:2,height:62,margin:0,displayValue:true,fontSize:13,textMargin:3});
      const printer=state.configs[$('settings-local').value]?.printer_path||$('settings-printer').value||'Star BSC10';
      win.document.open();win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Calibración BSC10</title><style>@page{size:80mm 116mm;margin:0}*{box-sizing:border-box}html,body{width:80mm;height:116mm;margin:0;padding:0;color:#000;background:#fff;font-family:Arial,sans-serif}.sheet{position:relative;top:11mm;width:72mm;height:100.1mm;margin:0 auto;border:.25mm solid #000;overflow:hidden;background:repeating-linear-gradient(90deg,transparent 0,transparent 9.75mm,#000 9.75mm,#000 10mm)}.inner{position:absolute;inset:2.5mm;background:#fff;padding:2.5mm}.line{position:absolute;left:0;width:100%;border-top:.25mm solid #000}.start{top:1mm}.after{top:85mm}.measure{font:700 7pt monospace}.title{font-size:17pt;font-weight:800}.medium{font-size:11pt;font-weight:700}.small{font-size:7.5pt}.codes{display:grid;grid-template-columns:27mm 1fr;gap:3mm;align-items:center;margin-top:3mm}.codes img{width:25mm;height:25mm;image-rendering:pixelated}.codes svg{width:37mm;height:18mm}.guide{position:absolute;left:3mm;right:3mm;bottom:2.5mm;padding-top:1.5mm;border-top:.25mm solid #000;font:700 6.8pt monospace;background:#fff}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="sheet"><i class="line start"></i><i class="line after"></i><div class="inner"><div class="measure">576 puntos · 72 mm · 203 dpi</div><div class="title">Texto grande · Ñandú</div><div class="medium">Texto mediano · áéíóú</div><div class="small">Texto pequeño · SUCAN BSC10</div><div class="codes"><img src="${qr}" alt="QR"><div>${svg.outerHTML}</div></div><p class="small">Las líneas verticales están separadas 10 mm. El rectángulo debe medir 72 × 100,1 mm.</p></div><div class="guide">IMPRESORA: ${html(printer)} · ESCALA 100 % · SIN MÁRGENES · SIN AJUSTAR</div></div><script>onload=()=>setTimeout(()=>print(),250)<\/script></body></html>`);win.document.close();
    }catch(error){if(win&&!win.closed)win.close();fail(error);}
  }
  function quickStorageKey(local){return `sucan_reserva_link_${local}`;}
  async function renderQuickLink(local){if(!isAdmin())return;const panel=$('quick-link-panel');panel.innerHTML='<div class="empty">Consultando enlace…</div>';try{const loc=localByName(local),status=await rpc('op_reserva_enlace_estado',{p_local:loc.id}),token=localStorage.getItem(quickStorageKey(local));if(!status.exists){panel.innerHTML='<p>No existe un enlace para este local.</p><button class="button primary" type="button" data-generate-link>Generar enlace</button>';return;}if(!token){panel.innerHTML=`<p>El local tiene un enlace ${status.active?'activo':'pausado'}, pero este navegador no conserva su dirección.</p><button class="button warning" type="button" data-generate-link>Reemplazar y mostrar enlace</button>`;return;}const url=`${location.origin}/reservas#${token}`;panel.innerHTML=`<div class="quick-link"><div class="quick-qr" id="quick-qr"></div><div><div class="quick-url">${html(url)}</div><div class="quick-actions"><button class="button primary small" type="button" data-copy-link>Copiar</button><button class="button secondary small" type="button" data-toggle-link="${status.active?'pausar':'reactivar'}">${status.active?'Pausar':'Reactivar'}</button><button class="button warning small" type="button" data-generate-link>Reemplazar</button></div></div></div>`;new QRCode($('quick-qr'),{text:url,width:132,height:132,colorDark:'#111119',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});}catch(error){panel.innerHTML=`<div class="empty">${html(error.message)}</div>`;}}
  async function generateLink(){if(!isAdmin())return;const local=$('settings-local').value,loc=localByName(local);try{const result=await rpc('op_reserva_crear_enlace',{p_local:loc.id});localStorage.setItem(quickStorageKey(local),result.token);renderQuickLink(local);toast('Enlace rápido generado.');}catch(error){fail(error);}}
  async function toggleLink(action){if(!isAdmin())return;const local=$('settings-local').value,loc=localByName(local);try{await rpc('op_reserva_configurar_enlace',{p_local:loc.id,p_accion:action});renderQuickLink(local);toast(action==='pausar'?'Enlace pausado.':'Enlace reactivado.');}catch(error){fail(error);}}
  async function copyQuickLink(){if(!isAdmin())return;const local=$('settings-local').value,token=localStorage.getItem(quickStorageKey(local));if(!token)return;await navigator.clipboard.writeText(`${location.origin}/reservas#${token}`);toast('Enlace copiado.');}

  function customProduct(){openAction(`<form class="action-form" id="custom-form"><h2>Agregar producto manualmente</h2><p>Usalo solamente si el producto no aparece en el padrón.</p><label class="field"><span>Código *</span><input class="input" id="custom-code" maxlength="80" required></label><label class="field"><span>Nombre *</span><input class="input" id="custom-name" maxlength="240" required></label><button class="button primary" type="submit">Agregar producto</button></form>`);$('custom-form').onsubmit=e=>{e.preventDefault();const codigo=clean($('custom-code').value,80),nombre=clean($('custom-name').value,240);if(!codigo||!nombre)return toast('Código y nombre son obligatorios.','error');closeAction();addProduct({codigo,nombre});};}

  function refreshVisibleReservationData(){
    if(document.visibilityState==='hidden'||!state.actor)return;
    if(state.current?.reservation?.id&&!$('detail-modal').hidden)return openDetail(state.current.reservation.id,{silent:true});
    if(['active','history'].includes(state.view))return loadList(state.view,{silent:true});
  }
  function startRealtimeFallback(error){
    if(error)console.warn('[Reservas] Realtime no disponible; se usará actualización periódica.',error);
    state.channel=null;state.realtimeMode='polling';
    if(!state.realtimeTimer)state.realtimeTimer=setInterval(refreshVisibleReservationData,15000);
  }
  function bindRealtime(){
    if(state.channel||state.realtimeTimer)return;
    let channel;
    try{
      channel=db.channel(`reservas-${state.actor.local}-${Date.now()}`)
        .on('postgres_changes',{event:'*',schema:'public',table:'op_reservas'},()=>{if(['active','history'].includes(state.view))loadList(state.view,{silent:true});})
        .on('postgres_changes',{event:'INSERT',schema:'public',table:'op_reserva_comentarios'},payload=>{if(state.current?.reservation?.id===payload.new.reserva_id)openDetail(payload.new.reserva_id,{silent:true});});
      state.channel=channel;
      channel.subscribe(status=>{
        if(status==='SUBSCRIBED'){state.realtimeMode='realtime';return;}
        if(!['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(status))return;
        if(state.channel===channel)state.channel=null;
        try{Promise.resolve(db.removeChannel(channel)).catch(()=>{});}catch(_error){}
        startRealtimeFallback();
      });
    }catch(error){
      try{if(channel)Promise.resolve(db.removeChannel(channel)).catch(()=>{});}catch(_error){}
      startRealtimeFallback(error);
    }
  }
  function debounce(fn,delay=260){let t;return(...args)=>{clearTimeout(t);t=setTimeout(()=>fn(...args),delay);};}

  $('reservation-form').addEventListener('submit',createReservation);$('new-local').addEventListener('change',()=>{state.orderCandidates=[];state.orderCandidatesLocal=null;renderNewItems();});$('new-purpose').addEventListener('change',syncPurposeFields);$('new-web-delivery').addEventListener('change',syncPurposeFields);
  $('product-search').addEventListener('input',debounce(()=>{if(state.productSearchType!=='barras')searchProducts();},90));$('product-search').addEventListener('keydown',onProductSearchKeydown);$('customer-search').addEventListener('input',debounce(searchCustomers));$('custom-product-button').addEventListener('click',customProduct);
  $('active-search').addEventListener('input',debounce(()=>loadList('active')));$('history-search').addEventListener('input',debounce(()=>loadList('history')));['active-state','active-local'].forEach(id=>$(id).addEventListener('change',()=>loadList('active')));['history-state','history-local'].forEach(id=>$(id).addEventListener('change',()=>loadList('history')));
  $('guide-button').addEventListener('click',showGuide);$('refresh-button').addEventListener('click',async()=>{if(state.current?.reservation?.id&&!$('detail-modal').hidden)return openDetail(state.current.reservation.id,{silent:true});if(['active','history'].includes(state.view))return loadList(state.view,{silent:true});if(state.view==='settings'){await refreshContext();return renderSettings();}resetForm();});$('settings-local').addEventListener('change',()=>{fillScheduleOriginOptions();renderSettings();});$('save-settings').addEventListener('click',saveSettings);$('print-calibration').addEventListener('click',printCalibration);$('schedule-type').addEventListener('change',renderScheduleType);$('save-schedule').addEventListener('click',saveSchedule);$('cancel-schedule-edit').addEventListener('click',resetScheduleForm);
  document.addEventListener('click',async event=>{
    const searchType=event.target.closest('[data-product-search-type]');if(searchType)return setProductSearchType(searchType.dataset.productSearchType);
    const tab=event.target.closest('[data-view]');if(tab){if(tab.dataset.view==='new'&&state.view!=='new')resetForm();return showView(tab.dataset.view);}
    if(event.target.closest('[data-open-new]')){resetForm();return showView('new');}if(event.target.closest('[data-cancel-form]'))return cancelReservationForm();const vb=event.target.closest('[data-view-button]');if(vb)return showView(vb.dataset.viewButton);
    const card=event.target.closest('[data-reservation-id]');if(card)return openDetail(card.dataset.reservationId);
    if(event.target.closest('[data-close-modal]'))return closeDetail();if(event.target.closest('[data-print-created]')){closeAction();return printLabel();}const copyCreated=event.target.closest('[data-copy-created-link]');if(copyCreated){return navigator.clipboard.writeText(copyCreated.dataset.copyCreatedLink).then(()=>toast('Enlace de seguimiento copiado.')).catch(error=>fail(error));}if(event.target.closest('[data-close-action]'))return closeAction();
    const pi=event.target.closest('[data-product-index]');if(pi)return addProduct($('product-results')._rows[Number(pi.dataset.productIndex)]);if(event.target.closest('[data-custom-product]'))return customProduct();
    const ci=event.target.closest('[data-customer-index]');if(ci)return selectCustomer($('customer-results')._rows[Number(ci.dataset.customerIndex)]);
    const split=event.target.closest('[data-split-item]');if(split)return splitItem(Number(split.dataset.splitItem));const remove=event.target.closest('[data-remove-item]');if(remove){state.newItems.splice(Number(remove.dataset.removeItem),1);return renderNewItems();}
    const save=event.target.closest('[data-save-item]');if(save)return saveItem(save.dataset.saveItem);const edit=event.target.closest('[data-edit-item]');if(edit)return actionEditItem(edit.dataset.editItem);const link=event.target.closest('[data-link-order]');if(link)return linkOrder(link.dataset.linkOrder);if(event.target.closest('[data-add-comment]'))return addComment();
    const next=event.target.closest('[data-next-step]')?.dataset.nextStep;if(next==='receive')return actionRegisterArrival();if(next==='finish')return actionFinish();if(next==='exception')return actionException();if(next?.startsWith('state:'))return actionAdvanceState(next.slice(6));
    const action=event.target.closest('[data-detail-action]')?.dataset.detailAction;if(action==='edit')return beginEditReservation();if(action==='delete')return actionDelete();if(action==='progress')return actionProgress();if(action==='finish')return actionFinish();if(action==='link-order')return actionLinkOrder();if(action==='exception')return actionException();if(action==='cancel')return actionCancel();if(action==='correct-close')return actionCorrectClose();if(action==='print')return printLabel();
    const editScheduleButton=event.target.closest('[data-edit-schedule]');if(editScheduleButton)return editSchedule(editScheduleButton.dataset.editSchedule);const toggleScheduleButton=event.target.closest('[data-toggle-schedule]');if(toggleScheduleButton)return toggleSchedule(toggleScheduleButton.dataset.toggleSchedule);if(event.target.closest('[data-generate-link]'))return generateLink();const tl=event.target.closest('[data-toggle-link]');if(tl)return toggleLink(tl.dataset.toggleLink);if(event.target.closest('[data-copy-link]'))return copyQuickLink();
    if(!event.target.closest('.customer-search'))$('customer-results').hidden=true;if(!event.target.closest('.product-search'))$('product-results').hidden=true;
  });
  $('new-items').addEventListener('change',event=>{if(event.target.matches('[data-item-field]'))syncItemField(event.target);});
  $('detail-modal').addEventListener('click',e=>{if(e.target===$('detail-modal'))closeDetail();});$('action-modal').addEventListener('click',e=>{if(e.target===$('action-modal'))closeAction();});
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.realtimeMode==='polling')refreshVisibleReservationData();});
  addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('action-modal').hidden)closeAction();else if(!$('detail-modal').hidden)closeDetail();}});
  init().catch(error=>{$('boot').hidden=true;$('access-missing').hidden=false;fail(error,'init');});
})();
